'use strict';
(() => {
const D=globalThis.RA.D;
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline: https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:`${w}.q${i+1}`,senseId:`${w}.s${q.s}`,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('run out','Run out is built from run plus out; the phrasal verb developed the sense of a supply reaching its end, and a period of validity reaching its end.',[C('run out.s1','通用','We ran out of clean water before the hikers reached the next station.','徒步者到达下一站前，干净饮用水就用完了。','run out of + supply','不及物短语动词常接 of + 被耗尽的物品。','no water remains.','通用'),C('run out.s2','通用','My travel card runs out at the end of June, so I need to renew it.','我的交通卡六月底到期，所以需要续办。','a ticket/pass/agreement runs out','短语动词也可表示票证或协议到期。','validity ends in June.','通用')],M('We ran out of fuel, so the full tank kept the car moving for another hundred miles.','We ran out of fuel, so the car stopped until we found more.','说燃油用完就不能同时说油箱仍满并继续行驶。','meaning'),[Q(1,'If a shop runs out of bread, it…','has no bread left','has just baked extra bread','has stopped selling bread forever','Run out of a supply means use all of it.','meaning'),Q(2,'A passport that runs out next week…','will reach the end of its validity','will be filled with new pages automatically','will become a running route','This sense applies to tickets, cards, and agreements expiring.','context'),Q(1,'Which phrase is correct?','run out of patience','run out from patience','run patience out of to','The common construction is run out of something.','collocation'),Q(1,'In “Our milk ran out,” milk…','was completely used up','expired as a legal document','flowed across the room','This uses the supply-exhaustion sense.','meaning')]);
P('run through','Run through combines run with through; the phrase can mean rehearse or review from beginning to end, and also extend through every part of something.',[C('run through.s1','通用','Before the interview, Mina ran through her answers with a friend.','面试前，米娜和朋友从头到尾快速过了一遍自己的回答。','run through a list/plan/lines','接名词宾语，表示快速复习或演练全部内容。','answers reviewed in sequence.','通用'),C('run through.s2','通用','A narrow stream runs through the garden and feeds the pond.','一条窄溪穿过花园，为池塘供水。','run through + place/material','表示线、道路、液体或特征贯穿某物。','stream crosses garden.','通用')],M('The actors ran through the scene by skipping every line and never practicing it.','The actors ran through the scene by rehearsing it from beginning to end.','run through台词是演练一遍，不是完全跳过。','meaning'),[Q(1,'To run through a presentation before giving it means to…','rehearse it from beginning to end','cancel it without reading it','run across the building','The phrase can mean review or rehearse all of something.','meaning'),Q(2,'A road runs through a town when it…','extends across the town','ends before reaching the town','is rehearsed by the residents','Sense 2 describes something passing through every part.','context'),Q(1,'Which phrase is natural?','run through the checklist','run through to the checklist it','run the checklist throughly of','Run through takes the material being reviewed as its object.','collocation'),Q(2,'In “A red vein runs through the stone,” the vein…','is present across the stone','is a list the stone rehearses','has run out of the stone','This is the sense of extending throughout something.','meaning')]);
P('run-on','Run-on is formed from run on and describes language that continues where a sentence or layout should stop.',C('run-on.s1','语言','The editor split the run-on sentence after “garden” and added a full stop.','编辑在“花园”后把这个连写句断开，并加了句号。','a run-on sentence','形容词修饰 sentence，指本应断开的句子仍连在一起。','independent clauses lacked punctuation.','语言'),M('The teacher called it a run-on sentence because every independent clause had been correctly separated with full stops.','The teacher called it a run-on sentence because independent clauses were joined without suitable punctuation.','句子结构已正确断开就不是run-on sentence。','meaning'),[Q(1,'A run-on sentence is one that…','joins thoughts without a needed grammatical break','contains exactly one short clause','is spoken while jogging','Run-on describes writing that continues past a required break.','meaning'),Q(1,'Which noun commonly follows run-on in this grammar sense?','sentence','sailor','sachet','Run-on sentence is the established grammar term.','collocation'),Q(1,'The editor marks two independent clauses joined only by a comma. The sentence is…','a run-on','a runway','a rung','The clauses need a stronger boundary than a comma alone.','context'),Q(1,'Run-on is formed from which words?','run + on','rung + out','rust + on','The adjective is the compound form of the phrasal verb run on.','word-formation')]);
P('run-up','Run-up combines run and up; it names either preparation time before an event or a short approach run to gain speed.',[C('run-up.s1','通用','In the run-up to the launch, engineers tested every safety system twice.','发射前的准备阶段，工程师把每套安全系统测试了两遍。','in the run-up to + event','名词短语常用 in the run-up to 表示事件前的准备时期。','tests happen before launch.','通用'),C('run-up.s2','运动','The jumper took a short run-up before clearing the bar.','跳高运动员在越过横杆前助跑了一小段。','take a run-up','运动语境中指起跳或投掷前的助跑。','athlete gains speed.','运动')],M('In the run-up to the election, the campaign began only after all results were announced.','In the run-up to the election, the campaign intensified before voting began.','run-up指重要事件之前的一段时间，而非事件之后。','meaning'),[Q(1,'The run-up to a conference is…','the period beforehand when preparations are made','the final report written months afterward','a ladder rung in the hall','The first sense is the preparation period before an event.','meaning'),Q(2,'A long-jumper takes a run-up to…','build speed before jumping','slow down after landing','repair the runway','The second sense is a short approach run.','context'),Q(1,'Which phrase is idiomatic?','in the run-up to the vote','on the run-up from the vote at','a run-up of voting after','In the run-up to introduces the approaching event.','collocation'),Q(2,'Which sentence uses the athletic sense?','She measured her run-up before the long jump.','The run-up to the summit involved months of talks.','The summit ran out in May.','A measured approach before a jump is the athletic sense.','meaning')]);
P('rungs','Rung, from Old English hrung, names a crossbar of a ladder; rungs is its plural and also figuratively means levels of rank or progress.',[C('rungs.s1','通用','He climbed the last two rungs carefully while holding the ladder steady.','他扶稳梯子，小心地爬上最后两级横档。','climb/stand on a rung','名词复数，指梯子上供脚踩的横档。','feet use ladder bars.','通用'),C('rungs.s2','社会','After years as an assistant, she moved up the rungs of the company hierarchy.','做了多年助理后，她在公司层级中逐步晋升。','the lower/top rungs of a ladder/hierarchy','比喻等级制度中的级别。','career advancement.','社会')],M('He stepped on the rungs between the ladder’s side rails because they were the wheels that rolled it forward.','He stepped on the rungs between the ladder’s side rails to climb.','梯子的rungs是横档，不是滚轮。','meaning'),[Q(1,'The rungs of a ladder are…','the crossbars a climber steps on','the two long side rails only','the wheels under the ladder','Rungs are the ladder’s steps or bars.','meaning'),Q(2,'Moving up the rungs of a firm means…','advancing through levels of rank','walking down a staircase','using a ladder to repair a roof','Rungs can metaphorically mean levels in a hierarchy.','context'),Q(1,'Which phrase is natural?','climb the rungs of the ladder','climb the ladder rungses','climb on rungs to the ladder from','Rungs are climbed as the steps of a ladder.','collocation'),Q(2,'“She reached a higher rung in her career” means she…','advanced to a higher level','fell from a ladder','changed to a lower salary','The figurative sense is a level of progress or rank.','meaning')]);
P('running costs','Running costs combines running (ongoing operation) and costs; it refers to regular expenses needed to keep a business, machine, or vehicle operating.',C('running costs.s1','商业','The efficient heating system cut the building’s running costs during winter.','高效供暖系统降低了这栋楼冬季的日常运营开支。','reduce/cover running costs','复数名词，指持续运营所需的经常性成本。','expenses recur while building operates.','商业'),M('The company’s running costs included only the one-time purchase price and no ongoing expenses.','The company’s running costs included recurring fuel, staffing, and maintenance expenses.','running costs是运营期间反复产生的开销，不是只有一次性购置价。','meaning'),[Q(1,'A business’s running costs are…','regular expenses of keeping it operating','the profit made when it closes','the ladder rungs in its office','Running costs are ongoing operating expenses.','meaning'),Q(1,'Which item is most clearly a running cost for a delivery fleet?','fuel bought every week','the one-time purchase of its first building','a customer’s refund','Recurring fuel is paid to keep operations going.','context'),Q(1,'Which phrase is natural?','cut the running costs','cut the running costed','run the costs throughing','Running costs is the standard noun phrase for operating expenses.','collocation'),Q(1,'A new motor uses less electricity each month. It may lower the machine’s…','running costs','rungs','run-up','The saving reduces a recurring cost of operating the machine.','meaning')]);
P('runoff','Runoff is formed from run off; it refers to water flowing over land or a deciding contest held after no winner gets enough votes.',[C('runoff.s1','环境','Heavy rain carried fertilizer in the runoff from the field into the stream.','暴雨把田地径流中的肥料冲进了溪流。','surface/stormwater runoff','名词指没有渗入土壤、沿地面流动的水。','rainwater carries fertilizer.','环境'),C('runoff.s2','政治','Neither candidate won a majority, so the election will go to a runoff next month.','两名候选人都没有获得多数票，因此下个月将举行决选。','an election/runoff between + candidates','名词也指无人达到规定多数后举行的第二轮竞选。','no candidate reached majority.','政治')],M('The runoff soaked straight into the soil, leaving no water flowing over the field.','The runoff flowed over the field before draining into the stream.','若水全部渗入土里，就没有地表径流。','meaning'),[Q(1,'Rainwater runoff is water that…','flows across the ground instead of soaking in','is stored only inside a cloud','runs along a runway','Runoff is surface water after rain or snowmelt.','meaning'),Q(2,'An election runoff is held when…','no candidate has the required majority','one candidate has already won by a landslide','the election is cancelled permanently','The second round decides a contest without a majority winner.','context'),Q(1,'Which phrase is natural?','agricultural runoff entered the lake','runoff of candidates soaked into the soil','the runoff ran out of an election','Runoff can modify water from farms.','collocation'),Q(2,'The two finalists face a runoff. This is…','a further contest to determine the winner','water flowing off a hillside','a program execution period','The political sense is a deciding second contest.','meaning')]);
P('runt','Runt is an older term for the smallest or weakest animal in a litter; its deeper history is uncertain.',C('runt.s1','动物','The runt of the litter needed extra care until it grew strong enough to feed.','这窝幼崽中最小最弱的一只需要额外照料，直到它能有力地进食。','the runt of the litter','名词，指一窝动物中最小或最弱的一只。','smallest young animal needs care.','动物'),M('The runt was the largest and strongest animal in the litter and needed no special care.','The runt was the smallest and weakest animal in the litter and needed extra care.','runt指一窝中最小或最弱的个体。','meaning'),[Q(1,'The runt of a litter is usually…','the smallest or weakest young animal','the animal that gives birth','the oldest animal in the group','Runt describes the smallest or weakest one in a litter.','meaning'),Q(1,'Why might a farmer give a runt extra attention?','It may be smaller and weaker than its littermates.','It is always the parent of the litter.','It is the largest animal by definition.','The word highlights its relatively small or weak size.','context'),Q(1,'Which phrase is standard?','the runt of the litter','the runt on the litter’s mother','the litter’s rung','Of the litter identifies the group it belongs to.','collocation'),Q(1,'Which animal could be called a runt?','the smallest pig in a group of newborn pigs','the strongest adult boar on the farm','a ladder bar in a barn','The term applies to an unusually small young animal.','meaning')]);
P('runtime','Runtime combines run and time; in computing it means the time a program is executing or the duration required for an operation.',C('runtime.s1','计算机','A runtime error stopped the script when it tried to divide by zero.','脚本试图除以零时发生运行时错误，因而停止。','runtime error/environment; program runtime','名词，指程序执行期间，也用于描述执行时间。','error occurs while executing.','计算机'),M('The runtime error appeared before the program was launched, while no code was executing.','The runtime error appeared while the program was executing.','runtime error发生于程序运行期间，不是启动前。','context'),[Q(1,'A runtime error occurs…','while a program is executing','only while a computer is switched off','after every file has been deleted','Runtime refers to the program’s execution period.','meaning'),Q(1,'A film with a runtime of 90 minutes lasts…','90 minutes','90 kilometres','90 computer files','Runtime can mean the duration of a work or process.','context'),Q(1,'Which phrase is standard in software?','runtime environment','run time environmented','runtime to execution of','Runtime environment describes where a program executes.','collocation'),Q(1,'In “shorten the runtime,” runtime refers to…','how long the process takes','the number of ladder rungs','how much rain flows over land','The word can name an operation’s duration.','meaning')]);
P('runway','Runway combines run and way; it names a prepared strip for aircraft or a raised path used by models.',[C('runway.s1','航空','The aircraft waited at the end of the runway until air traffic control cleared takeoff.','飞机在跑道尽头等待，直到空管批准起飞。','take off from/land on a runway','名词，指飞机起降的长条场地。','aircraft waits to take off.','航空'),C('runway.s2','时尚','The designer sent the collection’s final model down the runway in a silver coat.','设计师让最后一位模特穿着银色外套走上T台。','walk down/on the runway','名词也指时装模特走秀的狭长台道。','model displays clothing.','时尚')],M('The airliner landed safely on the runway, the narrow raised path used by fashion models.','The airliner landed safely on the runway, the prepared strip for aircraft.','飞机在航空跑道上降落；模特T台是runway的另一义项，语境不同。','context'),[Q(1,'An aircraft runway is…','a prepared strip for takeoffs and landings','a path in a fashion show only','a small ladder crossbar','Runway sense 1 is an airport surface for planes.','meaning'),Q(2,'A model walks down a runway to…','display clothing during a fashion show','prepare an aircraft for takeoff','measure road running costs','The fashion sense names the raised show path.','context'),Q(1,'Which phrase is correct?','land on the runway','land in the runway to','runway the plane over','Planes land on a runway.','collocation'),Q(2,'“The designer’s collection reached the runway” most likely means it…','was shown in a fashion presentation','was loaded onto an aircraft','was repaired after rusting','Runway can refer to the model’s catwalk.','meaning')]);
P('rupture','From Latin ruptura “a breaking,” from rumpere “to break”; rupture can be a sudden break, the resulting tear, or a serious break in relations.',[C('rupture.s1','工程','The old pipe may rupture if pressure rises beyond its safe limit.','如果压力超过安全限值，旧管道可能会突然破裂。','a pipe/artery ruptures; rupture under pressure','动词，指突然用力破裂。','pressure breaks pipe.','工程'),C('rupture.s2','医学','The scan showed a small rupture in the ligament near her knee.','扫描显示她膝盖附近的韧带有一处小裂口。','a rupture in + tissue/material','名词，指爆裂或撕裂形成的裂口。','scan finds tear.','医学'),C('rupture.s3','社会','The disputed border created a rupture between the two former allies.','有争议的边界在这两个昔日盟友之间造成了关系破裂。','a rupture between/in relations','名词也指团体或关系的彻底断裂。','allies no longer agree.','社会')],M('The pipe ruptured without breaking, splitting, or leaking even though it stayed fully intact.','The pipe ruptured and split under the rising pressure.','rupture表示破裂，不能同时保持完好且没有泄漏。','meaning'),[Q(1,'If a pipe ruptures, it…','breaks open suddenly','expires without damage','becomes a runway','Rupture as a verb means break open forcefully.','meaning'),Q(2,'A rupture in a ligament is…','a tear in the tissue','a new political election','a clean unbroken surface','Sense 2 names the physical tear.','context'),Q(3,'A rupture between allies describes…','a complete break in their relationship','a pipe carrying runoff','a small difference in clothing','The figurative sense is a serious split in relations.','meaning'),Q(1,'Which preposition fits? “A rupture ___ relations”','in','of to','at from','Rupture in relations is a natural construction.','grammar')]);
P('rural','From Latin ruralis, from rus “countryside”; rural describes the countryside, especially farming areas and their communities.',[C('rural.s1','地理','They moved from the crowded capital to a rural village surrounded by fields.','他们离开拥挤的首都，搬到一个田野环绕的乡村。','rural area/life/community','形容词修饰地区或生活方式，表示乡村的。','village among fields.','地理'),C('rural.s2','教育','Rural schools may need buses because students live far apart across farming districts.','由于学生分散居住在农业地区，乡村学校可能需要校车。','rural school/health service','也可指与农业地区居民相关的服务或问题。','students live far apart.','教育')],M('The rural village stood in the countryside, but the report described it as a densely packed city centre.','The rural village stood among farms well outside the city.','乡村地区与人口密集的市中心形成对照。','distinction'),[Q(1,'A rural community is located…','in the countryside','in a crowded city centre by definition','inside an aircraft runway','Rural means belonging to or typical of the countryside.','meaning'),Q(2,'A rural school may face…','long travel distances for students living across farming areas','a runway model shortage','an election runoff every week','Rural education relates to schools and people in farming areas.','context'),Q(1,'Which phrase is natural?','rural life','rurality life of','a rural in village people','Rural is an adjective that modifies life or area.','grammar'),Q(1,'Which is the opposite setting of a rural village?','a dense urban centre','a farm outside town','a country lane','Rural contrasts with urban or city-based.','meaning')]);
P('rush','From Old English ryscan “rush, move quickly”; rush means move quickly, act too hastily, or a sudden quick movement/busy period.',[C('rush.s1','通用','Paramedics rushed the injured cyclist to the nearest hospital.','急救人员迅速把受伤的骑车人送往最近的医院。','rush someone to + place','及物动词，表示迅速送某人到某处。','urgent transport.','通用'),C('rush.s2','通用','Do not rush into signing the contract before reading every clause.','读完每一条款前，不要匆忙签合同。','rush into + decision/action','也指做事过快、缺少考虑。','signing too quickly is risky.','通用'),C('rush.s3','通用','A rush of customers filled the store just before closing time.','关门前，一阵顾客涌入商店。','a rush of + people/activity; rush hour','名词，可指突然的快速涌动或繁忙时段。','many customers arrive suddenly.','通用')],M('She rushed into the contract after spending several weeks checking every clause with a lawyer.','She rushed into the contract without checking its clauses.','经过数周仔细审阅就不是匆忙贸然签约。','meaning'),[Q(1,'Paramedics rushed a patient to hospital. They…','took the patient there very quickly','asked the patient to wait for a month','ran out of medical supplies','Rush someone to a place means transport them quickly.','meaning'),Q(2,'To rush into a decision is to…','make it too quickly without enough thought','postpone it indefinitely','move up a career rung','This sense warns against hasty action.','context'),Q(3,'A rush of visitors is…','a sudden large flow of visitors','one visitor arriving next week','a careful review of a contract','Rush as a noun can describe sudden movement or activity.','meaning'),Q(2,'Which phrase is natural?','rush into signing','rush at signing into of','rush a signing to into','Rush into is followed by a noun or -ing action.','grammar')]);
P('rushing','Rushing is the present participle of rush, from Old English ryscan; as an adjective it describes something flowing or moving very fast.',C('rushing.s1','自然','We could barely hear the guide beside the rushing stream.','在奔流的溪水旁，我们几乎听不清向导说话。','a rushing river/stream/water','形容词修饰水流等，表示快速向前流动。','fast water masks speech.','自然'),M('The rushing stream stood perfectly still, with no water moving in any direction.','The rushing stream moved quickly past the rocks.','静止不动的水流不能称为rushing。','meaning'),[Q(1,'A rushing stream is…','flowing forward very fast','completely dry','a stream that has run out','Rushing describes rapid flow or movement.','meaning'),Q(1,'Which noun commonly follows rushing in this sense?','water','salary','rung','Rushing water is a natural collocation.','collocation'),Q(1,'The waterfall drowned out conversation because of the…','rushing water','rustproof metal','run-up to the trip','Fast-flowing water can be noisy.','context'),Q(1,'Rushing is the -ing form of…','rush','rung','rupture','Rushing is formed from the verb rush.','word-formation')]);
P('Russia','Russia is the country name, from Medieval Latin Russia and ultimately the name of the Rus people; it can also refer collectively to its government or people.',[C('Russia.s1','地理','Russia stretches across eastern Europe and northern Asia.','俄罗斯横跨东欧和北亚。','in/from/to Russia','专有名词表示国家，首字母大写。','country spans two regions.','地理'),C('Russia.s2','政治','Russia issued a statement through its foreign ministry.','俄罗斯通过外交部发布了一份声明。','Russia said/announced/denied','国家名可转喻指该国政府或官方机构。','government speaks through ministry.','政治')],M('They visited Russia, the country spanning eastern Europe and northern Asia, but wrote its name in lowercase as russia.','They visited Russia and wrote the country’s name with a capital letter.','国家专名Russia需大写。','spelling'),[Q(1,'Russia is…','a country in eastern Europe and northern Asia','a type of ladder rung','a spice used in rice','Russia names a large country across Europe and Asia.','meaning'),Q(2,'“Russia denied the report” most likely means…','the Russian government or officials denied it','every individual Russian personally spoke','a river denied the report','A country name may stand for its government.','context'),Q(1,'Which spelling is correct for the country?','Russia','russia','RUSSiA','Country names are capitalized as proper nouns.','spelling'),Q(1,'Which phrase is grammatical?','travel to Russia','travel Russia to the','travel on Russia by','The preposition to marks the destination country.','grammar')]);
P('rust','From Old English rūst, a Germanic word; rust is the reddish coating on iron or steel, and as a verb it means to become or make rust-covered.',[C('rust.s1','材料','The iron gate developed a layer of rust after years of rain and neglect.','多年淋雨失修后，铁门表面形成了一层锈。','a coat/patch of rust; remove rust','名词，指铁或钢遇水和空气后形成的红褐色物质。','iron exposed to moisture.','材料'),C('rust.s2','材料','If left outdoors, the unpainted tools will rust before spring.','如果放在室外不管，这些未上漆的工具到春天前就会生锈。','metal rusts; rust in damp conditions','动词，表示金属生锈，也可使之生锈。','tools corrode outdoors.','材料')],M('The iron gate rusted, but its surface stayed perfectly free of any reddish corrosion.','The iron gate rusted and developed reddish corrosion.','rust作为动词就是形成锈蚀。','meaning'),[Q(1,'Rust on an iron gate is…','a reddish coating caused by exposure to air and water','a protective layer of fresh paint','a small ladder step','Rust forms on iron or steel under exposure to moisture and air.','meaning'),Q(2,'If tools rust outdoors, they…','become covered with corrosion','become a runway','lose all their weight immediately','Rust as a verb means become rusty.','context'),Q(1,'Which phrase is natural?','remove rust from the hinge','remove rust of the hinge at','rust the hinge away from of','Rust can be removed from a metal object.','grammar'),Q(2,'Which sentence uses rust as a verb?','The steel bolts rusted in the rain.','A patch of rust stained the gate.','The gate has rust on it.','In the first option, rusted describes an action or change.','meaning')]);
P('rustic','From Latin rusticus “of the countryside,” from rus “country”; rustic describes country life or something plain and simply made.',[C('rustic.s1','生活','They rented a rustic cottage with a stone fireplace in the hills.','他们在山里租了一间带石砌壁炉的乡村小屋。','a rustic cottage/charm/setting','形容词，指乡村风格或乡村生活的。','cottage in countryside.','生活'),C('rustic.s2','设计','The café used rustic wooden tables with rough, unfinished edges.','咖啡馆使用了边缘粗糙、未经精细修饰的乡村风格木桌。','rustic furniture/decor','也指朴素、粗犷或未经精加工的制作风格。','rough simple furniture.','设计')],M('The room’s rustic furniture was polished to a flawless, ornate finish and looked like modern chrome machinery.','The room’s rustic furniture was simple and showed rough natural wood.','精致华丽的机械风格与朴素粗犷的rustic风格相反。','distinction'),[Q(1,'A rustic cottage is likely to…','have a country style','be a downtown glass skyscraper','be a medical prescription','Rustic often describes the countryside or country life.','meaning'),Q(2,'Rustic wooden shelves may look…','plain and roughly finished','highly polished and ornate','covered in water runoff','The second sense describes simple, rough workmanship.','context'),Q(1,'Which collocation is natural?','rustic charm','rustic to charmingly','rusticism charm of','Rustic charm is a common phrase for country-style appeal.','collocation'),Q(1,'Rustic comes from a Latin word meaning…','of the countryside','without rust','to move quickly','Latin rusticus means rural or country-like.','word-formation')]);
P('rustproof','Rustproof combines rust and proof in the sense “resistant to”; it describes metal protected from rust or unlikely to rust.',C('rustproof.s1','材料','The manufacturer supplied rustproof screws for the seaside balcony.','制造商为海边阳台配了防锈螺钉。','rustproof coating/steel/screws','形容词，表示经过处理或不易生锈。','salt air exposure.','材料'),M('The rustproof screws developed heavy rust after a single dry day indoors.','The rustproof screws resisted corrosion during years in salty air.','rustproof意为防锈，不能用来描述轻易锈蚀的螺钉。','meaning'),[Q(1,'Rustproof metal is…','treated or unlikely to rust','already covered in heavy corrosion','a metal ladder rung','Rustproof means resistant to rust.','meaning'),Q(1,'Where would rustproof screws be especially useful?','on a seaside balcony exposed to salty air','inside a dry paper envelope','in a sentence about an election','They resist corrosion in a damp salty environment.','context'),Q(1,'Which phrase is correct?','rustproof coating','rust-proofed to proof rust','rustproofingly coat','Rustproof can directly modify a noun such as coating.','grammar'),Q(1,'In rustproof, proof means…','resistant to or protected against','full of','the person who repairs','The compound uses proof in the resistant-to sense.','word-formation')]);
P('rusty','Rusty is formed from rust + -y; it means covered with rust or, figuratively, less skilled after a period without practice.',[C('rusty.s1','材料','The rusty hinge squeaked whenever the garden gate moved.','花园门一动，生锈的铰链就吱呀作响。','rusty iron/hinge/tool','形容词，指铁或钢表面有锈。','corroded hinge squeaks.','材料'),C('rusty.s2','技能','After a decade away from the piano, Leo felt rusty during his first lesson.','十年没碰钢琴后，利奥第一堂课弹得有些生疏。','rusty at/in + skill','比喻因久未练习而不如以前熟练。','lack of practice.','技能')],M('I was rusty at French because I had practiced it every day for years and never forgotten a word.','I was rusty at French because I had not practiced it for years.','长期天天练习并未遗忘，不能解释技能生疏。','context'),[Q(1,'A rusty hinge is…','covered with reddish corrosion','made of soft cloth','a well-rehearsed musical skill','The literal sense describes rust on metal.','meaning'),Q(2,'If a pianist feels rusty after ten years away, the pianist…','is less skilled from lack of practice','has become covered in metal corrosion','has just learned the instrument perfectly','Rusty can figuratively mean out of practice.','context'),Q(2,'Which phrase is natural?','rusty at chess','rusty to chessing','rusty with play chess at','Rusty at a skill is a common construction.','grammar'),Q(1,'Which sentence uses the literal sense?','A rusty nail stained the wood.','I am rusty at Italian after a long break.','Her rusty memory improved with practice.','A nail can be physically corroded.','meaning')]);
P('rut','Rut is from Old English rut “track, groove”; it means a wheel-made track in soft ground, or a dull, unchanging way of life.',[C('rut.s1','道路','The delivery van slipped into a rut on the muddy farm lane.','送货车在泥泞的农场小路上陷进了一道车辙。','a rut in the road; fall/get stuck in a rut','名词，指车轮在松软地面压出的深槽。','wheels left a track.','道路'),C('rut.s2','生活','After years of repeating the same routine, she felt stuck in a rut.','重复同样的日常多年后，她觉得自己陷入了沉闷的一成不变。','be/get stuck in a rut','比喻枯燥、难以改变的生活或习惯。','unchanging routine.','生活')],M('The truck sank into a rut, a smooth raised bridge built above the muddy road.','The truck sank into a rut, a deep track pressed into the muddy road.','rut是地面凹陷车辙，不是高起的桥。','meaning'),[Q(1,'A rut in a muddy road is…','a deep track made by wheels','a raised runway for planes','a ladder’s top rung','Rut sense 1 is a groove or track in soft ground.','meaning'),Q(2,'Being stuck in a rut means…','repeating a dull, unchanging routine','being promoted to a higher rank','being safely protected from harm','The figurative sense is a boring pattern that is hard to change.','context'),Q(1,'Which phrase is idiomatic?','stuck in a rut','stuck at rut of','stuck a rut into','The fixed phrase is be or get stuck in a rut.','collocation'),Q(1,'A car leaves deep marks in wet soil. The marks are…','ruts','rungs','runoffs','Ruts are tracks pressed into soft ground by wheels.','meaning')]);
P('ruthless','Ruthless combines ruth, an older word for pity or compassion, with -less; it means cruel or relentlessly determined without concern for those harmed.',[C('ruthless.s1','人物','The ruthless general ordered the village emptied despite the civilians’ pleas.','尽管平民苦苦哀求，这名残酷的将军仍下令清空村庄。','a ruthless attack/leader','形容词，表示残忍、毫不怜悯。','pleas ignored.','人物'),C('ruthless.s2','商业','The ruthless competitor would break any agreement if it brought her a larger contract.','只要能拿到更大的合同，这位无情的竞争者会撕毁任何协议。','ruthless in pursuit of + goal','也指为达目的不顾他人利益。','goal outweighs fairness.','商业')],M('The ruthless commander spared every enemy soldier and paused the attack to hear each plea.','The ruthless commander ignored pleas and continued the attack.','一再怜悯并停止攻击与毫不留情相矛盾。','meaning'),[Q(1,'A ruthless leader is…','cruel and showing little or no pity','gentle and unwilling to make decisions','someone who climbs a ladder','Ruthless means without compassion.','meaning'),Q(2,'A ruthless company pursuing a contract may…','ignore who is harmed while chasing its goal','give up every opportunity to protect rivals','run out of printer ink','The second sense emphasizes determined self-interest.','context'),Q(1,'Which phrase is natural?','a ruthless competitor','a ruthlessly competitor','a ruthless of competitor','Ruthless is an adjective modifying competitor.','grammar'),Q(1,'The suffix -less in ruthless contributes the sense…','without','full of','in the manner of','Ruthless literally contains the privative suffix -less.','word-formation')]);
P('ruthlessly','Ruthlessly is formed from ruthless + -ly; it describes acting without compassion or stopping at nothing to reach an aim.',C('ruthlessly.s1','通用','The editor ruthlessly removed every paragraph that repeated an earlier point.','编辑毫不留情地删掉了每一段重复先前观点的内容。','cut/compete ruthlessly','副词修饰动作，表示无情地、不留余地地。','editor removes material decisively.','通用'),M('The editor ruthlessly retained every weak paragraph because she felt too compassionate to remove anything.','The editor ruthlessly removed weak paragraphs to make the chapter concise.','因同情而全部保留与ruthlessly删改相反。','meaning'),[Q(1,'To cut a report ruthlessly is to cut it…','without hesitation or mercy','only after adding every repeated point','by running a race','Ruthlessly describes decisive, uncompromising action.','meaning'),Q(1,'Which sentence is grammatical?','They competed ruthlessly for the contract.','They ruthless competedly for the contract.','They competed ruthless for the contractly.','The -ly form is the adverb modifying competed.','grammar'),Q(1,'A manager removes all wasteful spending even when departments object. The manager acts…','ruthlessly','safely','rustproof','This describes uncompromising action to reach a goal.','context'),Q(1,'Ruthlessly is formed by adding -ly to…','ruthless','ruth','ruthful','The adverb derives from the adjective ruthless.','word-formation')]);
P('rye','From Old English ryge, a Germanic name for the grain; rye can mean the plant, its flour, or bread made from it.',[C('rye.s1','农业','Rye grows in cool regions where some other cereal crops struggle.','在其他谷类作物难以生长的凉爽地区，黑麦仍能生长。','grow/harvest rye','不可数名词指黑麦这种谷物植物。','crop grows in cool climate.','农业'),C('rye.s2','饮食','He ordered rye with soup instead of the restaurant’s white bread.','他点了黑麦面包配汤，而不是餐厅的白面包。','rye bread/flour; a slice of rye','也指用黑麦制成的面粉或面包。','bread choice.','饮食')],M('The bakery advertised rye bread but baked it entirely from wheat, with no rye flour or grain.','The bakery made its rye bread with rye flour.','纯小麦制品不应称为黑麦面包。','meaning'),[Q(1,'Rye is…','a cereal grain that grows well in cool areas','a type of fish with a sail-like fin','a salt solution','Rye sense 1 names a grain plant.','meaning'),Q(2,'A slice of rye at lunch most likely means…','bread made from rye grain','raw rye growing in a field','a piece of a ladder','Rye also names the bread made from the grain.','context'),Q(1,'Which phrase is natural?','rye flour','rye of flouring','rye flouring bread of','Rye commonly modifies flour or bread.','collocation'),Q(2,'A diner asks for rye instead of white. The diner asks for…','a kind of bread','a darker shade of metal rust','a runway ticket','Rye is often used as a shortened name for rye bread.','meaning')]);
P('s','The letter name and form descend through the Latin letter S and Greek sigma; the more remote history of the alphabetic sign is uncertain.',[C('s.s1','语言','The word “student” begins with a lowercase s.','“student”一词以小写字母s开头。','the letter s; lowercase/uppercase S','名词，指英语字母表中的第十九个字母。','spelling uses alphabet letter.','语言'),C('s.s2','符号','On the old chart, S marks the unit used for seconds.','在旧图表上，S表示秒所用的单位符号。','S as a symbol for + unit','大写S在某些记号系统中代表特定单位或数值。','notation key defines sign.','符号')],M('She wrote “student” with a lowercase z as its first letter, although the word starts with s.','She wrote “student” with a lowercase s as its first letter.','拼写student的首字母是s，不是z。','spelling'),[Q(1,'Which letter begins the word “student”?','s','r','t','Student begins with the nineteenth English letter, s.','spelling'),Q(2,'In a chart legend, a capital S may function as…','a notation sign defined by that system','a lowercase spelling of every word','a ladder rung','The source also records S as a symbol in some notations.','context'),Q(1,'Which form is lowercase?','s','S','5','The lowercase form is s; uppercase is S.','meaning'),Q(1,'S occupies which position in the English alphabet?','nineteenth','seventh','twenty-sixth','S follows R and precedes T, so it is nineteenth.','meaning')]);
P('sabbatical','From late Latin sabbaticus and Greek sabbatikos, ultimately from Hebrew shabbat “Sabbath”; a sabbatical is leave from regular duties, often for study or rest.',[C('sabbatical.s1','教育','The professor used her sabbatical to study archival letters in another country.','这位教授利用学术休假到另一个国家研究档案信件。','take/spend a sabbatical; sabbatical leave','名词，指获准暂离常规工作的休假期。','leave used for research.','教育'),C('sabbatical.s2','通用','The university approved a sabbatical year for staff who had completed six years of service.','大学批准为服务满六年的员工安排一年休假。','a sabbatical year/leave','形容词修饰leave/year，表示与休假期有关。','approved period away from duties.','通用')],M('During his sabbatical, the lecturer taught a full daily schedule and was not released from any regular duties.','During his sabbatical, the lecturer stepped away from regular teaching to pursue research.','sabbatical的关键是暂离日常职责。','meaning'),[Q(1,'A professor on sabbatical is usually…','temporarily away from regular duties for study, travel, or rest','dismissed permanently for poor performance','working every ordinary shift without leave','A sabbatical is a period of authorized leave.','meaning'),Q(2,'Which noun can sabbatical naturally modify?','leave','rungs','runoff','Sabbatical leave refers to a period away from normal work.','collocation'),Q(1,'Why might an academic take a sabbatical?','to conduct research away from routine teaching','to make a ladder rustproof','to run through a runway','Research is a common purpose of academic leave.','context'),Q(1,'The distant source of sabbatical is a Hebrew word for…','Sabbath','salary','sailing','The word ultimately comes from Hebrew shabbat.','word-formation')]);
P('sabotage','From French sabotage, from saboter “damage, bungle”; sabotage is deliberate damage or obstruction, and to sabotage is to cause it.',[C('sabotage.s1','社会','Investigators found evidence of sabotage after someone disabled the factory’s alarm system.','有人破坏了工厂的警报系统后，调查人员发现了蓄意破坏的证据。','an act of sabotage; industrial sabotage','名词，指蓄意损坏或妨碍设备、计划等。','alarm disabled deliberately.','社会'),C('sabotage.s2','通用','A software bug sabotaged the launch by corrupting the customer database.','软件故障破坏了发布工作，把客户数据库弄坏了。','sabotage a plan/system','动词，指故意破坏或阻挠某事。','launch undermined.','通用')],M('The technician sabotaged the machine by repairing every fault and making sure it worked perfectly.','The technician sabotaged the machine by deliberately disabling its controls.','修好故障并确保正常运转不是破坏。','meaning'),[Q(1,'Sabotage of a machine is…','deliberate damage or obstruction','routine maintenance that improves it','the machine’s running cost','Sabotage means purposeful damage or interference.','meaning'),Q(2,'A person who sabotages a launch may…','deliberately undermine its success','help every team meet its goals','take a sabbatical','The verb means damage or obstruct intentionally.','context'),Q(1,'Which phrase is idiomatic?','an act of sabotage','a sabotage of to','sabotageful actioned','An act of sabotage names a deliberate harmful act.','collocation'),Q(1,'Sabotage entered English from…','French','Old English','Swahili','The noun comes from French sabotage.','word-formation')]);
P('sabre','From French sabre, ultimately from Hungarian szablya; a sabre is a heavy curved sword or the fencing discipline using that weapon.',[C('sabre.s1','历史','The cavalry officer’s curved sabre hung in a glass case at the museum.','这名骑兵军官的弯刀挂在博物馆的玻璃展柜里。','a curved sabre; draw a sabre','名词，指刃口弯曲的重剑。','curved sword displayed.','历史'),C('sabre.s2','体育','She won the national sabre title after a close final bout.','她在一场势均力敌的决赛后赢得了全国佩剑冠军。','fence in sabre; the sabre event','也指使用军刀式佩剑的击剑项目。','fencing competition.','体育')],M('The museum labelled its straight, blunt rapier as a curved sabre used by cavalry.','The museum labelled its curved cavalry sword a sabre.','笔直的细剑不是词条所指的弯曲重剑。','distinction'),[Q(1,'A sabre is traditionally…','a long curved sword','a small paper sachet','a wooden ladder rung','The weapon sense is a heavy sword with a curved edge.','meaning'),Q(2,'In fencing, the sabre event uses…','a sabre-style weapon and target rules','only a foil with no blade','a swordfish fin','Sabre also names the fencing discipline.','context'),Q(1,'Which adjective commonly describes a sabre?','curved','saline','rustproof by definition','The weapon is distinguished by its curved cutting edge.','collocation'),Q(1,'The English word sabre came through…','French','Arabic','Old Norse','Sabre entered English from French.','word-formation')]);
P('SAC','SAC is an initialism of Strategic Air Command, the former United States command responsible for strategic bombers and missiles; the capitalized form is distinct from ordinary “sac.”',C('SAC.s1','历史','SAC directed the United States’ strategic bomber force during the Cold War.','冷战期间，SAC负责指挥美国的战略轰炸机部队。','SAC stands for Strategic Air Command','专名缩写，三个大写字母分别对应名称首字母。','command oversees bombers.','历史'),M('The archive identified SAC as a small plant cavity and wrote the biological noun in all capitals.','The archive identified SAC as Strategic Air Command and reserved lowercase sac for the biological pouch.','全大写SAC表示机构缩写；生物学普通名词写作小写sac。','spelling'),[Q(1,'In the Cold War context, SAC stands for…','Strategic Air Command','Small Aircraft Cabin','Southern Atlantic Coast','The letters abbreviate Strategic Air Command.','meaning'),Q(1,'Why is SAC written in capitals?','It is an initialism made from the organization’s initials.','It is the plural of the noun sac.','It is an adjective meaning safe.','Each capital letter represents a word in the command’s name.','spelling'),Q(1,'Which sentence uses SAC as the historical organization?','SAC managed strategic bomber operations.','A pollen sac opened in the flower.','The nurse prepared saline.','The bomber-command context identifies the initialism.','context'),Q(1,'Which spelling distinguishes the ordinary biological noun?','sac','SAC','S.a.c.','The source distinguishes lowercase sac from the all-capitals initialism.','spelling')]);
P('sachet','From French sachet, a diminutive of sac “bag”; a sachet is a small packet or a scented bag of dried flowers or powder.',[C('sachet.s1','日常','The hotel left a sachet of shampoo beside each guest’s sink.','酒店在每位客人的洗手池旁放了一小袋洗发水。','a sachet of + powder/liquid/cream','名词，指盛一份物质的小包装袋。','single-use shampoo packet.','日常'),C('sachet.s2','家居','She tucked a lavender sachet into the drawer to keep the clothes smelling fresh.','她把一袋薰衣草香包放进抽屉，让衣服保持清香。','a scented sachet; sachet of lavender','也指装香粉或干花的小香袋。','dried flowers perfume drawer.','家居')],M('She opened a sachet of shampoo, a large metal trunk designed to store winter coats.','She opened a sachet of shampoo, a small packet holding one portion.','小袋装一次用量不是大型金属箱。','meaning'),[Q(1,'A sachet of shampoo is…','a small packet holding one portion','a full-size storage cabinet','a curved sword','Sachet sense 1 means a small bag or packet.','meaning'),Q(2,'A lavender sachet in a drawer is used to…','give clothes a pleasant scent','hold a ladder upright','measure a salary','The scented pouch contains flowers or perfume.','context'),Q(1,'Which phrase is natural?','a sachet of powder','a sachet for powdering of by','sachetted powderly','Of introduces the sachet’s contents.','grammar'),Q(1,'The word sachet came into English from…','French','Russian','Greek','Sachet is borrowed from French.','word-formation')]);
P('sack','From Old English sacc, via Latin and Greek from Semitic sources; sack is a large bag, to dismiss someone, or to plunder a town.',[C('sack.s1','日常','The farmer filled a sack with potatoes and tied its mouth shut.','农场主把一袋土豆装满，并把袋口扎紧。','a sack of + goods; fill a sack','名词，指大而结实的袋子，也可指一袋的量。','bag carries potatoes.','日常'),C('sack.s2','工作','The firm sacked two employees after they falsified their expense claims.','两名员工伪造报销单后，公司解雇了他们。','sack someone for + reason','动词，非正式地表示解雇某人。','employment ends.','工作'),C('sack.s3','历史','The invading troops sacked the town and carried away its stored grain.','入侵军队洗劫了小镇，带走了储存的粮食。','sack a city/town','动词也可指用暴力洗劫城镇或建筑。','invaders loot town.','历史')],M('The manager sacked her, meaning he promoted her to a permanent position with a higher salary.','The manager sacked her, meaning he dismissed her from the job.','sack作动词的职场义是解雇，不是提拔。','meaning'),[Q(1,'A sack of potatoes is…','a large bag containing potatoes','a job dismissal letter only','a meeting before an election','Sack sense 1 names a large bag or its contents.','meaning'),Q(2,'If a company sacks an employee, it…','dismisses that person from the job','gives the person a raise','asks the person to pack a bag','The informal employment sense means fire or dismiss.','context'),Q(3,'In a historical account, troops sacked a town. They…','plundered it by force','built new houses there','held a sabbatical there','Sack sense 3 means loot a town.','meaning'),Q(1,'Which phrase is correct?','sack someone for misconduct','sack to someone with misconduct','sacked someone at misconducting','For can introduce the reason for dismissal.','grammar')]);
P('sacred','From Latin sacer “holy, set apart,” through French sacré; sacred means religiously holy or so important that it must be deeply respected.',[C('sacred.s1','宗教','Pilgrims removed their shoes before entering the sacred shrine.','朝圣者进入这座神圣的圣地前脱下了鞋子。','a sacred place/text/object','形容词，表示与宗教或神圣事物相关。','shrine treated with reverence.','宗教'),C('sacred.s2','价值','The family regarded Sunday dinner together as a sacred tradition.','这家人把周日共进晚餐视为不可轻易改变的重要传统。','something is sacred to + person','引申指极其重要、不可侵犯的事物。','tradition deeply valued.','价值')],M('The temple called the shrine sacred but encouraged visitors to damage it for entertainment.','The temple called the shrine sacred and asked visitors to treat it with reverence.','称为神圣之物意味着应尊重保护，而非鼓励损害。','meaning'),[Q(1,'A sacred shrine is…','connected with religion and treated with deep respect','a place where no one has any respect','a bag used to carry grain','Sacred sense 1 means holy or religiously revered.','meaning'),Q(2,'If privacy is sacred to a family, the family…','considers it too important to violate','wants everyone to publish private details','has forgotten the family tradition','Sacred can mean deeply valued and not to be violated.','context'),Q(1,'Which phrase is natural?','a sacred text','a sacredly text of','a sacredness textly','Sacred is an adjective modifying text.','grammar'),Q(1,'The Latin source sacer meant…','holy or set apart','running quickly','made of salt','Sacred ultimately derives from Latin sacer.','word-formation')]);
P('sacrifice','From Latin sacrificium “an offering to a god,” from sacer “holy” and facere “make”; sacrifice means giving something up, a religious offering, or the act of surrendering something valued.',[C('sacrifice.s1','通用','She made a sacrifice by turning down a promotion to care for her father.','她为了照顾父亲放弃晋升机会，作出了牺牲。','make a sacrifice; sacrifice time/comfort','名词，指为较大目标放弃重要事物。','valuable opportunity given up.','通用'),C('sacrifice.s2','宗教','The ancient community brought an animal sacrifice to the altar.','古代社群把一只祭牲带到祭坛。','offer/make a sacrifice to + deity','名词，指献给神的祭物或祭祀行为。','offering placed at altar.','宗教'),C('sacrifice.s3','通用','He sacrificed his weekend to finish the emergency repairs.','他牺牲周末时间完成紧急维修。','sacrifice something for/to + purpose','动词，表示为了另一目标放弃珍视之物。','free time surrendered.','通用')],M('She sacrificed her weekend, meaning she kept it free and refused to work on the repairs.','She sacrificed her weekend by working through it to finish the repairs.','sacrifice时间表示放弃休息时间，不是保留空闲。','meaning'),[Q(1,'Making a sacrifice for a family member means…','giving up something valued to help them','receiving a payment from them','making a ladder out of wood','Sense 1 is the act of surrendering something important.','meaning'),Q(2,'An animal sacrifice in an ancient ceremony is…','an offering made to a god','a business expense','a sports warm-up','Sense 2 is the religious offering.','context'),Q(3,'He sacrificed sleep to complete the report. He…','gave up sleep so the report could be finished','slept through the deadline','made the report into a sacred object','The verb means surrender something for another aim.','meaning'),Q(1,'Which phrase is natural?','sacrifice time for a cause','sacrifice to time at a cause','sacrifice a cause with time for','One may sacrifice time for a purpose.','grammar')]);
P('sacrificial','From sacrifice + -al, ultimately from Latin sacrificium; sacrificial describes an offering in a religious rite or a willingness to give something up for others.',[C('sacrificial.s1','宗教','The temple records describe a sacrificial animal offered during the annual ceremony.','寺庙记载描述了年度仪式中献祭的动物。','a sacrificial offering/animal','形容词，指在宗教仪式中作为祭品献上的。','animal offered in ritual.','宗教'),C('sacrificial.s2','情感','Her sacrificial care for the injured neighbor continued through the long winter.','漫长的冬天里，她仍无私地照料受伤的邻居。','sacrificial love/care','也指愿意为他人放弃自身利益的。','care given at personal cost.','情感')],M('The sacrificial animal was kept solely as a pet and was never offered in the ceremony.','The sacrificial animal was offered during the ceremony.','未被献祭的宠物不符合此处的宗教义。','context'),[Q(1,'A sacrificial animal is one…','offered in a religious ceremony','kept only as a household pet','used to forecast the weather','Sacrificial can describe an offering in a rite.','meaning'),Q(2,'Sacrificial care for a neighbor suggests care that…','requires giving up something for that person','benefits only the caregiver','is performed by a machine','The figurative sense highlights selfless giving.','context'),Q(1,'Which phrase is natural?','sacrificial love','sacrifice loveable','sacrificially love as noun','Sacrificial is an adjective modifying love.','grammar'),Q(1,'Sacrificial is formed from sacrifice plus…','-al','-less','-er','The suffix -al forms an adjective meaning related to sacrifice.','word-formation')]);
P('sad','From Old English sæd, originally “sated, weary,” later “sorrowful”; sad describes unhappiness or something that causes sorrow or regret.',[C('sad.s1','情感','He felt sad when his best friend moved to another country.','最好的朋友搬到另一个国家后，他感到难过。','feel/look sad; sad about + event','形容词，表示感到或显露不快乐。','friend leaves.','情感'),C('sad.s2','评价','It is sad that the neighborhood library had to close.','社区图书馆不得不关闭，真令人惋惜。','a sad fact/story; it is sad that...','也可表示某事令人悲伤或遗憾。','closure causes sorrow.','评价')],M('She was sad about the good news because it made her cheerful and delighted.','She was sad about the bad news because it made her unhappy.','开心愉快的消息不会使她难过。','meaning'),[Q(1,'If someone feels sad, the person feels…','unhappy','hungry for salt','ready to sail','Sad describes unhappiness.','meaning'),Q(2,'“It is sad that the library closed” means the closure is…','a cause for sorrow or regret','a reason to celebrate','a sign of a safe building','This use comments on an event as regrettable.','context'),Q(1,'Which phrase is grammatical?','sad about the news','sadly about of news','sadness aboutly news','Sad is followed naturally by about to name a cause.','grammar'),Q(1,'Choose the opposite of sad in “She felt sad.”','happy','ruthless','rural','Happy contrasts with feeling unhappy.','meaning')]);
P('sadden','Sadden is formed from sad + -en, a verb-forming suffix meaning “make or become”; it means make someone feel unhappy.',C('sadden.s1','情感','The news of the canceled reunion saddened the whole family.','聚会取消的消息让全家人都感到难过。','sadden someone; be saddened by + news','及物动词，表示使某人悲伤。','family feels sorrow.','情感'),M('The announcement saddened the family, making everyone delighted and eager to celebrate.','The announcement saddened the family, making everyone unhappy.','delighted庆祝与感到悲伤相反。','meaning'),[Q(1,'To sadden someone is to…','make that person unhappy','protect the person from every danger','move the person to the countryside','Sadden is a causative verb meaning make sad.','meaning'),Q(1,'Which sentence is grammatical?','The loss saddened her.','The loss saddenly her.','The loss was sadden by her.','Sadden takes the person affected as its object.','grammar'),Q(1,'The ending -en in sadden helps form…','a verb meaning make sad','a noun meaning a sad feeling','an adverb meaning sadly','The suffix makes a verb from the adjective sad.','word-formation'),Q(1,'Which event would most likely sadden a child?','A beloved pet has gone missing.','The child receives a favorite gift.','The child wins a game.','A loss is a plausible cause of sadness.','context')]);
P('saddle','From Old English sadol, a Germanic word for a riding seat; saddle is a horse or bicycle seat, to put a saddle on a horse, or to burden someone with a problem.',[C('saddle.s1','交通','The cyclist adjusted the saddle before setting off on the long route.','骑车人出发走长途路线前调整了车座。','a horse/bicycle saddle','名词，指马鞍或自行车座。','seat adjusted before ride.','交通'),C('saddle.s2','交通','At dawn, the stable hand saddled the horse for the patrol.','黎明时，马厩工人为巡逻备好了马鞍。','saddle a horse','动词，表示把鞍装到马上。','horse prepared to ride.','交通'),C('saddle.s3','通用','The rushed handover saddled the new manager with several unresolved complaints.','仓促交接让新经理背上了几项尚未解决的投诉。','saddle someone with + burden/problem','比喻把不想要的责任或麻烦交给某人。','manager inherits problems.','通用')],M('The rushed handover saddled the manager with the complaints, meaning it relieved her of every responsibility.','The rushed handover saddled the manager with the complaints, leaving her responsible for resolving them.','saddle someone with a problem表示加给其负担，不是免除责任。','meaning'),[Q(1,'A bicycle saddle is…','the seat on the bicycle','the front wheel','the chain guard','Saddle sense 1 can name a bicycle seat.','meaning'),Q(2,'To saddle a horse is to…','put a riding seat on it','remove its reins permanently','make it run out of water','The verb sense is to equip a horse with a saddle.','context'),Q(3,'To saddle a colleague with extra work is to…','give the colleague an unwanted burden','free the colleague from all duties','promote the colleague to a higher rung','This figurative construction means impose a problem or duty.','meaning'),Q(3,'Which phrase is correct?','saddle someone with a problem','saddle someone of a problem','saddle a problem for someone with','The standard pattern is saddle someone with something.','grammar')]);
P('sadness','Sadness is formed from sad + -ness, the noun suffix naming a quality or state; it means an unhappy feeling or a sorrowful mood conveyed by a work.',[C('sadness.s1','情感','A deep sadness settled over the family after the farewell.','告别之后，一种深深的悲伤笼罩着这家人。','a feeling of sadness; sadness about/at + event','名词，指不快乐、心情沉重的感受。','family grieves after goodbye.','情感'),C('sadness.s2','文艺','The song’s quiet sadness comes through even in its gentle melody.','即使旋律轻柔，这首歌中淡淡的忧伤仍然显露出来。','the sadness of a story/song','也指故事、歌曲或场景表达出的悲伤氛围。','music conveys melancholy.','文艺')],M('The song’s sadness made listeners feel cheerful because it expressed unclouded joy throughout.','The song’s sadness made listeners feel low because it expressed loss and sorrow.','表达纯粹喜悦的歌曲不能以sadness为主要氛围。','context'),[Q(1,'Sadness is…','the feeling or state of being unhappy','the act of making a salary bill','a safe metal box','Sadness is the noun for the state of feeling sad.','meaning'),Q(2,'The sadness of a song refers to…','the sorrowful mood the song expresses','the singer’s salary','the song’s running costs','Sadness can name a mood conveyed by art.','context'),Q(1,'Which phrase is natural?','a feeling of sadness','a sadnessly feeling of','sadness to feeling by','A feeling of sadness is the standard construction.','grammar'),Q(1,'Which suffix in sadness turns sad into a noun?','-ness','-ly','-en','The suffix -ness names a state or quality.','word-formation')]);
P('safari','From Swahili safari “journey,” from Arabic safar “journey”; safari now usually means an expedition to observe wildlife, especially in Africa.',C('safari.s1','旅行','Their safari guide spotted elephants beside the track before the visitors did.','游客还没看见时，游猎向导已发现路边的大象。','go on/take a safari; safari guide','名词，指远行探险，如今尤指野生动物观察之旅。','wildlife spotted by guide.','旅行'),M('They went on safari to watch wildlife, but spent the entire trip inside a city museum with no expedition.','They went on safari across the reserve to watch wildlife.','没有远行或野外观察的城市参观不符合此义。','context'),[Q(1,'A wildlife safari is…','an expedition to observe animals in their natural habitat','a routine visit to a hair salon','a salary report','Safari now commonly describes a wildlife-watching trip.','meaning'),Q(1,'A safari guide helps visitors…','find and observe wildlife','repair a rusted gate','practice a fencing match','The guide leads the wildlife expedition.','context'),Q(1,'Which phrase is natural?','go on safari','go at safariing on','safari a wildlife with','Go on safari is a common expression.','collocation'),Q(1,'Safari ultimately comes from an Arabic word meaning…','journey','pity','holy','The Swahili word was borrowed from Arabic safar, “journey.”','word-formation')]);
P('safe','From Latin salvus “uninjured, healthy,” through Old French sauf; safe means protected from danger, unlikely to cause harm, or a locked strongbox.',[C('safe.s1','通用','The children arrived home safe after the storm delayed their train.','暴风雨耽误了火车，但孩子们平安到家。','safe from + danger; safe and sound','形容词，表示未受伤害或危险。','children unharmed.','通用'),C('safe.s2','健康','The water is safe to drink after it has been boiled.','水煮沸后饮用是安全的。','safe to + verb; safe for + person','形容词，表示不大可能造成伤害或失败。','boiling removes risk.','健康'),C('safe.s3','财务','She locked the emergency cash in the office safe.','她把应急现金锁进办公室的保险箱。','a wall/office safe; lock something in a safe','名词，指存放贵重物品的坚固带锁箱。','cash secured in box.','财务')],M('The water was safe to drink, although laboratory tests showed it contained a dangerous poison.','The water was safe to drink because tests found no harmful contamination.','含有危险毒物的水不可能被称为可安全饮用。','meaning'),[Q(1,'If a child is safe from danger, the child is…','protected from harm','certain to be injured','inside a salary bill','Safe sense 1 means free from danger.','meaning'),Q(2,'Water that is safe to drink is…','unlikely to harm someone who drinks it','guaranteed to taste sweet','a locked metal box','This sense concerns whether use or consumption may cause harm.','context'),Q(3,'An office safe is used to…','store valuables securely in a locked box','keep rainwater flowing over land','hold a horse saddle','Safe can be a noun naming a strong locked box.','meaning'),Q(2,'Which construction is standard?','safe to drink','safe drinking to','safe of drinking by','Safe to + verb describes an action unlikely to cause harm.','grammar')]);
P('safeguard','Safeguard joins safe and guard; it is a protective rule or device, and as a verb it means protect something against harm or loss.',[C('safeguard.s1','法律','Independent audits are an important safeguard against fraud.','独立审计是防止欺诈的重要保障措施。','a safeguard against + risk','名词，指防止伤害、滥用或损失的措施。','audit prevents fraud.','法律'),C('safeguard.s2','环境','The council planted trees to safeguard the riverbank from erosion.','委员会种植树木以保护河岸免遭侵蚀。','safeguard something from/against + harm','动词，表示保护某物免遭损害。','trees stabilize bank.','环境')],M('The audit was a safeguard against fraud because it concealed every transaction from reviewers.','The audit was a safeguard against fraud because it exposed suspicious transactions.','掩盖交易不能起到防止欺诈的保护作用。','meaning'),[Q(1,'A safeguard against fraud is…','a measure that helps prevent fraud','a plan to hide fraud from inspectors','a type of curved sword','Safeguard as a noun means a protective measure.','meaning'),Q(2,'To safeguard a riverbank is to…','protect it from damage such as erosion','remove every tree that holds the soil','make it salty','The verb means protect something against harm.','context'),Q(1,'Which phrase is natural?','a safeguard against abuse','a safeguard to abuse for','a safeguard by abusing','Against names the harm the measure is meant to prevent.','grammar'),Q(2,'Which sentence uses safeguard as a verb?','The law safeguards tenants from unfair eviction.','The law contains a safeguard.','A safeguard protects the public.','In the first sentence safeguards is an action verb.','meaning')]);
P('safely','Safely is formed from safe + -ly; it means in a way that avoids danger or, in “safely assume,” with adequate grounds for a conclusion.',[C('safely.s1','通用','The rescue team guided every hiker safely down the icy slope.','救援队引导每位徒步者安全地下了结冰的山坡。','arrive/travel safely; safely from + danger','副词修饰动作，表示避免危险或伤害。','hikers reach bottom without injury.','通用'),C('safely.s2','推理','Given the matching serial numbers, we can safely assume the parts came from one batch.','鉴于序列号一致，我们可以有充分根据地推断这些零件来自同一批次。','safely assume/conclude that...','固定用法表示有充分理由相信某判断正确。','evidence supports inference.','推理')],M('The hikers descended safely, although each one fell, was injured, and needed rescue.','The hikers descended safely without falling or being injured.','safe descent不能同时意味着每个人都跌倒受伤。','meaning'),[Q(1,'The hikers arrived safely means they arrived…','without being harmed','after being badly injured','with no reason to believe they arrived','Safely sense 1 means in a way that avoids harm.','meaning'),Q(2,'If we can safely assume the parts match, we…','have good evidence for that conclusion','are making a guess with no evidence','are protecting the parts from rust','This sense marks a reasonably well-supported inference.','context'),Q(1,'Which sentence uses safely as an adverb?','She crossed the bridge safely.','The safety bridge crossed her.','She was a safe crossing.','Safely modifies the action crossed.','grammar'),Q(2,'“We can safely conclude that the test worked” suggests…','the evidence supports the conclusion','the test must be repeated because nothing is known','the conclusion was reached by running','Safely here signals a justified inference.','meaning')]);
P('safety','Safety is formed from safe with the noun-forming suffix -ty; it names freedom from danger or the rules and devices that protect people.',[C('safety.s1','通用','Road safety improves when drivers slow down near the school.','司机在学校附近减速行驶时，道路安全会提高。','for safety; safety of + person/place','名词，指没有危险或伤害的状态。','slower driving lowers danger.','通用'),C('safety.s2','工作','The factory reviewed its fire-safety procedures after the alarm test.','警报测试后，工厂审查了消防安全规程。','fire/food/workplace safety','也指整体的保护规章、措施或装置。','procedures prevent workplace harm.','工作')],M('For safety, workers removed every guard from the machine while it was running.','For safety, workers fitted guards to the machine before it was run.','移除防护装置会增加而不是保障安全风险。','meaning'),[Q(1,'Safety on the road means…','being protected from danger and injury','driving as fast as possible','leaving every crossing unmarked','Safety is the state of being free from harm.','meaning'),Q(2,'A factory improves workplace safety by…','using rules and guards to prevent accidents','removing alarms and protective guards','increasing the running costs only','Safety can refer to protective rules and devices.','context'),Q(1,'Which phrase is standard?','for your own safety','for your safely','for safetyly','Safety is the noun that follows for.','grammar'),Q(1,'Which suffix turns safe into the noun safety?','-ty','-less','-en','Safety is formed from safe with the noun suffix -ty.','word-formation')]);
P('saffron','From Old French safran and Medieval Latin safranum, ultimately from Arabic zaʿfarān and Persian; saffron is the dried stigma spice or its deep yellow-orange color.',[C('saffron.s1','烹饪','A few strands of saffron gave the rice a fragrant golden colour.','几缕藏红花让米饭带上了芬芳的金黄色。','a pinch/strand of saffron; saffron rice','名词，指藏红花柱头制成的香料。','spice colours rice.','烹饪'),C('saffron.s2','颜色','The monks wore saffron robes that glowed against the grey stone walls.','僧侣穿着藏红花色长袍，在灰色石墙映衬下格外醒目。','saffron robes/yellow-orange','形容词，表示深黄带橙的颜色。','robe has orange-yellow hue.','颜色')],M('The cook added saffron, a blue dye made from the leaves of a seaweed.','The cook added saffron, the dried stigma spice that gives food a golden hue.','saffron是藏红花香料，不是海藻蓝色染料。','meaning'),[Q(1,'Saffron used in cooking is…','a spice made from dried crocus stigmas','a kind of rye bread','a metal coating that prevents rust','Saffron spice comes from dried stigmas of the crocus.','meaning'),Q(2,'Saffron robes are usually…','deep yellow-orange','bright blue-green','rust red only','The adjective names a golden orange-yellow color.','context'),Q(1,'Which phrase is natural?','a pinch of saffron','a pinch saffronly','a saffron for pinching of','A pinch of saffron is a natural measure phrase.','grammar'),Q(1,'Saffron reached English through French and Latin from…','Arabic and Persian sources','Old Norse saga','Swahili safari','The word’s route includes Arabic zaʿfarān and Persian.','word-formation')]);
P('saga','From Old Norse saga “story, saying”; saga is a long narrative of remarkable events or a prolonged, complicated sequence of real events.',[C('saga.s1','文学','The novel is a family saga following three generations across a century.','这部小说是一部家族传奇，讲述了一个家族跨越一世纪的三代人。','a family/historical saga','名词，指讲述非凡经历的长篇、分部故事。','narrative spans generations.','文学'),C('saga.s2','新闻','The delayed road project became a political saga of hearings, resignations, and new deadlines.','这项延期的道路工程变成了一场政治风波，牵涉听证、辞职和新期限。','a saga of + events; the saga continues','也指漫长复杂、持续发展的现实事件。','series of connected delays.','新闻')],M('The three-page report was a saga, although it contained only one brief, unrelated event.','The decades-long family story was a saga, unfolding through connected events over generations.','单一简短事件不符合saga所指的长篇或复杂连续发展。','meaning'),[Q(1,'A family saga is usually…','a long story following a family through many events','a short instruction for cooking rice','a ship’s sail','Saga sense 1 is an extended narrative.','meaning'),Q(2,'A political saga of delays and resignations is…','a long complicated series of connected events','one simple event with no consequences','a wildlife trip','The figurative sense applies to drawn-out real events.','context'),Q(1,'Which phrase is natural?','a saga of political delays','a saga at political delayly','a sago of political delays','Saga of introduces the events in the series.','grammar'),Q(1,'Saga entered English from…','Old Norse','Latin salvia','French sachet','Saga is borrowed from Old Norse.','word-formation')]);
P('sagacious','From Latin sagax “keen, perceptive,” related to sagire “perceive keenly”; sagacious describes wise judgment and sharp understanding.',C('sagacious.s1','人物','A sagacious mediator noticed that both sides wanted the same guarantee.','一位睿智的调解人察觉到双方其实都想要同一种保证。','a sagacious choice/observer; sagacious in + judgment','形容词，指对人和情形理解敏锐、判断明智。','mediator sees shared interest.','人物'),M('The sagacious judge ignored every relevant fact and reached a conclusion without understanding the case.','The sagacious judge weighed the relevant facts and recognized the central issue.','忽略证据、不了解案情不是明智敏锐的判断。','meaning'),[Q(1,'A sagacious decision is…','wise and based on sharp understanding','careless and uninformed','a decision about a salary bill','Sagacious means wise and perceptive.','meaning'),Q(1,'A sagacious editor notices a hidden inconsistency because the editor is…','shrewd in understanding the text','unable to read the text','covered in rust','The adjective describes perceptive judgment.','context'),Q(1,'Which noun does sagacious naturally modify?','judgment','saliva','runway','Sagacious judgment is a natural collocation.','collocation'),Q(1,'Sagacious ultimately relates to a Latin word meaning…','keen or perceptive','safe from danger','a long story','Its Latin source sagax means keen or perceptive.','word-formation')]);
P('sage','The wise-person sense came through Old French sage from Latin sapere “be wise”; the herb name comes from Latin salvia, so the two senses have distinct histories.',[C('sage.s1','人物','The village sage advised the council to repair the bridge before winter.','村里的智者建议委员会在冬天前修好桥梁。','a wise sage; consult a sage','名词，指以智慧和判断力著称的人。','elder gives sensible advice.','人物'),C('sage.s2','烹饪','She added chopped sage to the onions before stuffing the roast.','她在填馅前把切碎的鼠尾草加进洋葱里。','fresh/dried sage; sage leaves','名词，指叶子可用于烹饪调味的草本植物。','herb flavors food.','烹饪'),C('sage.s3','人物','His sage warning persuaded the team to test the brakes again.','他明智的警告说服团队再次检测刹车。','sage advice/words/counsel','形容词，表示有智慧、判断良好。','warning is prudent.','人物')],M('The chef added sage to the stew, claiming the herb was an elderly person renowned for wisdom.','The chef added sage, the aromatic herb, to the stew.','烹饪义的sage是香草，不是智者。','distinction'),[Q(1,'A village sage is…','a person known for wisdom','a plant whose leaves season food','a type of saltwater','Sage sense 1 names a wise person.','meaning'),Q(2,'A cook chops sage for a stew. Sage is…','an aromatic herb','a wise adviser','a ladder rung','The herb is a separate sense of sage.','context'),Q(3,'Sage advice is advice that is…','wise and sensible','salty and sour','carelessly rushed','The adjective sense means showing good judgment.','meaning'),Q(1,'Which sentence uses the herb sense?','Fresh sage scented the roasting vegetables.','The sage spoke wisely to the king.','She offered sage counsel.','The cooking context identifies the plant.','context')]);
P('sago','From Malay sagu, a name for starch obtained from palm stems; sago is the edible starch used in puddings and as small pearls.',C('sago.s1','饮食','The chilled sago pudding was served with mango after dinner.','晚餐后，大家吃了冰镇芒果西米布丁。','sago pudding; sago pearls','不可数名词，指从某些棕榈茎髓提取的淀粉。','starch dessert.','饮食'),M('The dessert was called sago pudding, but its pearls were made from metal and contained no edible starch.','The dessert was made with edible sago starch shaped into pearls.','含金属、不可食的颗粒不可能是sago淀粉。','meaning'),[Q(1,'Sago is…','starch extracted from the soft centre of certain palms','a long curved sword','a fish with pink flesh','Sago is an edible palm starch.','meaning'),Q(1,'Sago pearls may be used to make…','puddings and desserts','rustproof screws','aircraft runways','Sago is commonly used in pudding.','context'),Q(1,'Which phrase is natural?','sago pudding','sago to puddingly','sagoed puddinging','Sago commonly modifies pudding.','collocation'),Q(1,'The English word sago was borrowed from…','Malay','Old Norse','Latin','The name comes through Malay sagu.','word-formation')]);
P('saguaro','Saguaro is borrowed through Mexican Spanish; its deeper Indigenous-language source is uncertain. It names Carnegiea gigantea, a tall Sonoran Desert cactus with upward-reaching arms.',C('saguaro.s1','植物','A tall saguaro stood beside the trail, its arms silhouetted against the desert sunset.','一株高大的巨柱仙人掌立在步道旁，举起的侧枝映在沙漠落日中。','a saguaro cactus; saguaro arms','专有植物名，指索诺兰沙漠特有的树状巨大仙人掌。','distinctive cactus in desert.','植物'),M('The guide pointed to a saguaro, a short aquatic fern growing beneath the Arctic ice.','The guide pointed to a saguaro, a tall cactus native to the Sonoran Desert.','saguaro是沙漠巨柱仙人掌，不是北极水生蕨类。','meaning'),[Q(1,'A saguaro is…','a tall cactus native to the Sonoran Desert','a palm starch used in pudding','a small marine fish','Saguaro names the giant tree-like cactus Carnegiea gigantea.','meaning'),Q(1,'A saguaro’s “arms” are…','upward-reaching branches on the cactus','the gardener’s tools','a ladder’s crossbars','The cactus is recognized by arms that grow upward.','context'),Q(1,'Which phrase is natural?','a saguaro cactus','a saguaro of cactusing','a cactus salal','Saguaro is the common name of this cactus.','collocation'),Q(1,'The deeper source of the word saguaro is…','uncertain, though it entered English through Mexican Spanish','certainly Latin for salt','Old Norse for story','The Indigenous-language etymology is not settled.','word-formation')]);
P('sail','From Old English segl “sail,” of Germanic origin; sail is the cloth that catches wind, to travel by water, or to operate a boat.',[C('sail.s1','航海','The crew raised the sail when the wind began to fill it.','风开始吹鼓船帆时，船员升起了帆。','raise/lower/set sail','名词，指借风推动船只的大块帆布。','wind fills cloth.','航海'),C('sail.s2','旅行','We sailed across the lake before the storm reached the shore.','暴风雨抵达湖岸前，我们乘船横渡了湖面。','sail across/to + place','不及物动词，表示乘船在水面航行。','boat crosses lake.','旅行'),C('sail.s3','航海','Her family sails a small boat along the coast every summer.','她家每年夏天都会驾驶小船沿海岸航行。','sail a boat/ship','及物动词，表示驾驶或操控船只。','family controls boat.','航海')],M('The crew raised the sail, but it was a stone anchor that caught the wind and pushed the boat.','The crew raised the sail so the wind could push the boat forward.','帆借风推进船只，石锚不会兜风航行。','meaning'),[Q(1,'A ship’s sail is…','cloth that catches wind to move the boat','a metal box for valuables','a curved fencing sword','Sail sense 1 names the wind-catching cloth.','meaning'),Q(2,'We sailed across the lake means we…','traveled by boat over the water','walked around the lake on foot','ran out of the water','Sail can mean travel on water.','context'),Q(3,'Which sentence uses sail as a transitive verb?','She sails the boat herself.','The boat sails across the bay.','The sail caught the wind.','In the first sentence sail takes boat as its direct object.','grammar'),Q(1,'Which phrase is natural?','set sail at dawn','set a sail to dawning','sail the wind into a cloth','Set sail means begin a voyage.','collocation')]);
P('sailfish','Sailfish combines sail and fish, describing the large billfish whose tall dorsal fin resembles a sail.',C('sailfish.s1','动物','A sailfish’s tall dorsal fin appeared above the waves beside the research boat.','研究船旁的海浪上方露出一条旗鱼高高的背鳍。','a sailfish’s dorsal fin; catch/observe a sailfish','名词，指背鳍高大如帆的大型旗鱼。','fin resembles sail.','动物'),M('The guide identified the sailfish by its tiny hidden fin and four legs on the forest floor.','The guide identified the sailfish by its tall sail-like dorsal fin in the water.','旗鱼是鱼类，显著特征是高大的帆状背鳍。','meaning'),[Q(1,'A sailfish is known for its…','large sail-like dorsal fin','soft fur and paws','palm-derived starch','Its tall dorsal fin looks like a sail.','meaning'),Q(1,'Where would a researcher most likely see a sailfish?','swimming in the sea','climbing a dry desert cactus','inside a locked safe','Sailfish is a large marine billfish.','context'),Q(1,'Why is it called a sailfish?','Its tall dorsal fin resembles a sail.','It carries people on a boat.','It eats only cloth sails.','The name describes the fin’s sail-like appearance.','word-formation'),Q(1,'Which phrase is natural?','a sailfish broke the surface','a sailfish was planted in a garden','a sailfish of running costs','A fish can break the water’s surface as it swims.','collocation')]);
P('sailing','Sailing is formed from sail + -ing; as a noun it names travel by or control of a sailing boat, and as an adjective it describes sail-powered travel.',[C('sailing.s1','运动','Sailing became her favorite weekend sport after she joined the harbour club.','加入港口俱乐部后，帆船运动成了她最喜欢的周末活动。','go sailing; learn sailing','名词，指乘帆船或驾驶帆船的活动。','weekend boat sport.','运动'),C('sailing.s2','航海','The museum restored a sailing ship that had crossed the Atlantic a century ago.','博物馆修复了一艘一百年前横渡大西洋的帆船。','a sailing ship/boat','形容词修饰船只或旅行，表示使用帆航行的。','ship travels by sail.','航海')],M('The museum labelled the steam-powered ironclad a sailing ship, although it had no sails and used an engine.','The museum labelled the wind-powered vessel a sailing ship.','依靠蒸汽机而无帆航行的船不是sailing ship。','distinction'),[Q(1,'Sailing as a weekend sport involves…','traveling in or controlling a sailing boat','repairing a road after runoff','reading a salary bill','Sailing names the activity of using a sailing boat.','meaning'),Q(2,'A sailing ship is a ship that…','travels using sails','is always powered only by steam','cannot travel on water','The adjective describes sail-powered travel.','context'),Q(1,'Which phrase is natural?','go sailing on the lake','go sailingly to the lake on','go a sailings of lake','Go sailing is a common activity phrase.','collocation'),Q(2,'Which boat is most clearly a sailing boat?','one whose sails catch the wind','one moved only by an engine with no sails','one stored in a salon','The second sense concerns travel using sails.','meaning')]);
P('sailor','Sailor is formed from sail + -or, an agent suffix; it means a person who works aboard a seagoing vessel or someone who handles boat travel without getting seasick.',[C('sailor.s1','职业','The sailor checked the ropes before the cargo ship left the harbour.','货船离港前，水手检查了缆绳。','a sailor on/aboard a ship','名词，指在海上航行船只上工作的人。','crew member checks lines.','职业'),C('sailor.s2','航海','Even in rough water, she remained a good sailor and never felt ill.','即使海面颠簸，她仍很能适应乘船，从不晕船。','a good/poor sailor','也指乘船时不易或容易晕船的人。','traveler avoids seasickness.','航海')],M('The sailor checked the ship’s ropes, although she had never worked aboard a vessel and was only a passenger on shore.','The sailor checked the ship’s ropes as part of her work aboard the vessel.','若只在岸上、从未在船上工作，不能称为船员水手。','context'),[Q(1,'A sailor on a cargo ship is…','a person who works aboard the vessel','a person selling clothes on a runway','a ladder crossbar','Sailor sense 1 names a ship worker.','meaning'),Q(2,'A good sailor in rough water is someone who…','does not easily feel seasick','cannot swim or travel by boat','works only as a ship’s cook','Sense 2 can describe tolerance of boat motion.','context'),Q(1,'Which phrase is natural?','a sailor aboard the ship','a sailor into the ship aboard of','a sailing sailor on shiply','Aboard the ship identifies where the sailor works.','grammar'),Q(1,'The suffix -or in sailor most often identifies…','a person associated with an action or role','a place where salt is stored','a state of being sad','Sailor names a person who sails or works at sea.','word-formation')]);
P('saint','From Latin sanctus “holy,” through Old French saint; saint is a person formally honored for holiness or, informally, someone exceptionally kind and patient.',[C('saint.s1','宗教','The church calendar marks Saint Francis’s feast day in October.','教会历法把十月的一天标为圣方济各的纪念日。','Saint + personal name; a patron saint','名词，指教会因圣洁生活而尊崇的人。','church honors holy person.','宗教'),C('saint.s2','口语','You were a saint to watch my children while I was in hospital.','我住院期间你帮忙照看孩子，你真是太善良耐心了。','be a saint to + person; a saint of patience','口语中夸某人极有耐心、善良。','speaker praises kindness.','口语')],M('The church recognized him as a saint despite his life of cruelty and complete lack of compassion.','The church recognized him as a saint for a life of holiness and compassion.','残酷且毫无怜悯与圣人受尊崇的理由相反。','meaning'),[Q(1,'A church may honor a saint for…','a holy life','selling goods in a shop','having a high salary','Sense 1 is a person formally honored for holiness.','meaning'),Q(2,'Calling a helpful neighbor “a saint” informally means…','the neighbor is exceptionally kind and patient','the neighbor is a church building','the neighbor is a sailor','The informal sense is praise for unusual patience or kindness.','context'),Q(1,'Which phrase is natural?','Saint Peter','Peter saintly the','a saint of the church to','Saint commonly precedes the person’s name.','grammar'),Q(1,'Saint came into English through Old French from Latin…','sanctus, “holy”','saccus, “bag”','salvia, “sage”','The Latin source means holy.','word-formation')]);
P('saintly','Saintly is formed from saint + -ly; it describes unusually kind, patient, or morally good behavior resembling that expected of a saint.',C('saintly.s1','人物','Her saintly patience with the noisy children impressed their exhausted parents.','她对吵闹孩子表现出的圣人般耐心，让筋疲力尽的父母十分佩服。','saintly patience/kindness; behave saintly','形容词，表示善良、耐心到令人联想到圣人。','patience shown despite noise.','人物'),M('His saintly behavior involved mocking the children and refusing to help anyone in need.','His saintly behavior involved patiently helping the children and comforting anyone in need.','嘲弄他人、拒绝援助并非善良有耐心的行为。','meaning'),[Q(1,'Saintly patience is patience that is…','exceptionally kind and enduring','impatient and cruel','caused by a salary cut','Saintly describes behavior resembling a saint’s goodness.','meaning'),Q(1,'Which sentence uses saintly correctly?','The nurse showed saintly patience during the long night.','The nurse saintly showedly patience.','The saintly patience was a noun’s adverb.','Saintly is an adjective modifying patience.','grammar'),Q(1,'A neighbor quietly cares for everyone during a crisis. The neighbor may be called…','saintly','ruthless','saliferous','This describes exceptional kindness and moral goodness.','context'),Q(1,'Saintly is formed from saint plus…','-ly','-en','-ment','The suffix -ly forms the adjective saintly here.','word-formation')]);
P('sake','From Old English sacu “cause, dispute, matter,” related to German Sache “thing”; the noun survives chiefly in fixed phrases naming a reason or someone’s interest.',[C('sake.s1','通用','She accepted the transfer for the sake of her children’s education.','为了孩子们的教育，她接受了调职。','for the sake of + person/purpose','固定短语表示某行为的原因或目的。','transfer chosen for children.','通用'),C('sake.s2','通用','Please keep the original receipt for your own sake in case the item must be returned.','为了你自己的利益，请保留原始收据，以防需要退货。','for someone’s sake; for your own sake','表示某人的利益或福祉。','receipt benefits buyer.','通用')],M('For the sake of her children’s education, she chose the school that offered no classes and no teachers.','For the sake of her children’s education, she chose a school with strong teaching.','为了孩子的教育而选择完全没有课程和教师的学校违背目的。','context'),[Q(1,'She stayed for the sake of her children. She stayed…','because she wanted to benefit or protect them','because the children had already left','to board a sailing ship','For the sake of introduces a reason or purpose.','meaning'),Q(2,'Keep a receipt for your own sake means keep it…','for your own benefit','to benefit a stranger only','to make it rust','Sake sense 2 concerns someone’s interest or welfare.','context'),Q(1,'Which phrase is idiomatic?','for the sake of safety','for sake to the safety','at the safety sake of','The fixed form is for the sake of + noun.','collocation'),Q(1,'Sake is most often used today…','in set phrases such as “for the sake of”','as a common plural count noun','as an adjective before “children”','Its modern use is chiefly in fixed expressions.','usage')]);
P('salad','From Old French salade and Italian salata, ultimately from Latin sal “salt”; salad is a cold dish of vegetables or a cold mixture named for its main ingredient.',[C('salad.s1','饮食','We ordered a green salad with tomatoes, cucumber, and a lemon dressing.','我们点了一份配番茄、黄瓜和柠檬调味汁的绿色沙拉。','a green/side salad; salad dressing','名词，指冷食蔬菜菜肴。','vegetables served cold.','饮食'),C('salad.s2','饮食','For dessert, the children shared a bowl of fruit salad.','作为甜点，孩子们分吃了一碗水果沙拉。','fruit/potato/chicken salad','也指以某种主要原料命名的冷拌混合菜。','fruit is main ingredient.','饮食')],M('The restaurant served a hot bowl of plain boiling water and called it a green salad.','The restaurant served cold mixed vegetables with dressing as a green salad.','沙拉是凉拌菜，不是一碗热开水。','meaning'),[Q(1,'A green salad is usually…','a cold dish of vegetables','a hot drink made from rye','a locked metal box','Salad sense 1 is a vegetable dish.','meaning'),Q(2,'Fruit salad is named for…','the fruit that forms its main ingredient','the green leaves of sage only','the bowl’s material','This sense names a cold mixture after its main ingredient.','context'),Q(1,'Which phrase is natural?','salad dressing','saladly dressingness','dressing in salad of to','Dressing is the sauce commonly served with salad.','collocation'),Q(1,'The word salad ultimately relates to Latin sal, meaning…','salt','water','ship','The dish name traces through salata to Latin sal.','word-formation')]);
P('salal','Salal is the English name of Gaultheria shallon, a Pacific-coast shrub; its further word history is uncertain.',C('salal.s1','植物','The florist used glossy salal leaves to fill out the winter wreath.','花艺师用光亮的沙龙果叶填充冬季花环。','salal leaves/foliage; salal berries','名词，指北美太平洋沿岸的常绿灌木及其枝叶。','evergreen foliage in arrangement.','植物'),M('The florist called a desert cactus salal, although salal is a Pacific-coast shrub with leathery leaves.','The florist used salal, a Pacific-coast shrub, as evergreen filler in the arrangement.','沙龙果不是沙漠仙人掌，而是太平洋沿岸灌木。','distinction'),[Q(1,'Salal is…','a Pacific-coast shrub with leathery leaves and dark berries','a giant Sonoran cactus','a palm starch','Salal names Gaultheria shallon.','meaning'),Q(1,'A florist may use salal because it has…','long-lasting evergreen foliage','a sail-like dorsal fin','a metal rustproof coating','Its leaves provide durable greenery in arrangements.','context'),Q(1,'Which phrase is natural?','salal foliage','salal to foliageing','a salal of a cactus','Salal can modify foliage when naming its leaves.','collocation'),Q(1,'The deeper etymology of salal is…','uncertain','definitely Latin for salt','from Old Norse for story','The plant name’s deeper source is not confidently established.','word-formation')]);
P('salamander','From Greek salamandra through Latin; salamander names a lizard-like amphibian with a tail and soft, moist skin.',C('salamander.s1','动物','A spotted salamander sheltered under the wet log beside the pond.','一只带斑点的蝾螈躲在池塘边的湿木头下。','a spotted/fire salamander; salamander habitat','名词，指有尾、皮肤湿润的蝾螈类两栖动物。','amphibian hides in damp place.','动物'),M('The field guide identified the salamander as a dry-scaled desert bird with feathers and wings.','The field guide identified the salamander as a moist-skinned amphibian with a tail.','蝾螈是两栖动物，不是有羽毛的鸟。','distinction'),[Q(1,'A salamander is an…','amphibian with a tail and moist skin','insect with six wings','edible grain plant','Salamanders are lizard-like amphibians.','meaning'),Q(1,'Where might a salamander hide?','under a damp log','on a dry rooftop in direct sun','inside a salt shaker','Many salamanders favor moist shelter.','context'),Q(1,'Which phrase is natural?','a salamander under a log','a salamander of a salary bill','salamander to the running costs','A salamander may be found under a damp log.','grammar'),Q(1,'Salamander came into English through Latin from…','Greek','Swahili','Old English','Its recorded route is Greek through Latin.','word-formation')]);
P('salaried','Salaried is formed from salary + -ed; it describes workers paid a fixed amount for a period rather than by the hour.',C('salaried.s1','工作','The salaried engineers received the same monthly pay during the plant shutdown.','工厂停产期间，受薪工程师仍拿到相同的月薪。','salaried employee/staff/position','形容词，指按固定周期领取薪水的。','fixed monthly pay continues.','工作'),M('The salaried worker was paid only for each hour on the clock, with no fixed period-based pay.','The salaried worker received a fixed monthly amount rather than an hourly wage.','仅按小时付薪而无固定薪金不符合salaried的定义。','distinction'),[Q(1,'A salaried worker is paid…','a fixed amount for a period','only for each individual hour worked','only in food','Salaried contrasts with hourly-paid work.','meaning'),Q(1,'Which person is most likely salaried?','an engineer paid the same amount each month','a casual worker paid only per hour','a customer buying a salary bill','The fixed monthly pay matches the source sense.','context'),Q(1,'Which noun commonly follows salaried?','employee','runoff','saffron','Salaried employee is a common collocation.','collocation'),Q(1,'Salaried is formed from salary plus…','-ed','-en','-ness','The adjective uses the suffix -ed.','word-formation')]);
P('salary','From Latin salarium, historically associated with a salt allowance and ultimately sal “salt”; salary now means fixed pay, usually stated monthly or yearly.',[C('salary.s1','工作','Her annual salary increased after she completed the professional certification.','她完成职业资格认证后，年薪提高了。','annual/monthly salary; earn a salary','名词，指通常按月或年约定的固定工作报酬。','yearly pay increases.','工作'),C('salary.s2','工作','The post offers a salary of £42,000 a year plus a pension.','这个职位提供每年42,000英镑的薪水，另有养老金。','a salary of + amount; be on a salary','也指某专业职位所给的收入数额。','post specifies compensation.','工作')],M('Her salary was paid as one fixed yearly amount, but the company described it as the number of hours she worked.','Her salary was the fixed yearly pay for her work.','固定薪酬金额不是工时数量。','distinction'),[Q(1,'A salary is usually…','fixed pay stated for a month or year','a one-time gift unrelated to work','the cost of a sack of rye','Salary is regular fixed compensation for work.','meaning'),Q(2,'“The post offers a salary of £42,000” tells you…','the amount of pay attached to the job','how many people applied','the job’s running costs only','This construction names the compensation amount.','context'),Q(1,'Which phrase is correct?','an annual salary','a salary by annualing','salary of working annual','Annual salary is a natural noun phrase.','collocation'),Q(1,'Salary’s Latin ancestor salarium was associated with…','salt','sails','sadness','The historical word is linked to sal, Latin for salt.','word-formation')]);
P('salary bill','Salary bill combines salary and bill, with bill referring to an account or statement; it can mean a payroll list or an organization’s total wage expense.',[C('salary bill.s1','财务','The accountant checked the salary bill to confirm each employee’s monthly payment.','会计核对了工资清单，确认每名员工的月度付款。','prepare/check/pay a salary bill','名词，指列明员工应付工资的书面清单。','payroll list verified.','财务'),C('salary bill.s2','商业','The club reduced its salary bill by postponing new hires.','俱乐部推迟招聘，降低了工资总支出。','cut/increase the salary bill','也指机构支付员工工资的总额。','total payroll expense falls.','商业')],M('The accountant called the salary bill a list of monthly payments, then said it measured the club’s total wage expense rather than listing workers’ pay.','The accountant used salary bill for the employees’ pay list, and separately for the total payroll expense.','两个义项需依据上下文区分；若说“列出每人应付额”，不是仅说总成本。','distinction'),[Q(1,'A salary bill checked by an accountant may be…','a written list of what each worker is due','a story about a ship’s sail','a tax on salt only','Sense 1 is a payroll statement.','meaning'),Q(2,'A club cuts its salary bill by hiring fewer players. It reduces…','the total amount spent paying staff','the number of items on a restaurant bill','the sales of its merchandise','Sense 2 refers to total wage expense.','context'),Q(1,'Which phrase is natural?','reduce the salary bill','salary the bill reducement','bill the salary out at','Salary bill can be reduced or increased as a cost.','collocation'),Q(1,'Which clue points to the total-expense sense?','The report gives one organization-wide payroll total.','The document lists the amount due to each employee.','The page displays a single employee’s name.','An aggregate payroll figure is sense 2.','distinction')]);
P('sale','From Old English sala “act of selling,” related to sell; sale names the act of selling, a reduced-price period, or the amount/value sold.',[C('sale.s1','商业','The sale of the old cinema to a local charity was completed on Friday.','旧电影院出售给当地慈善机构的交易于周五完成。','for sale; the sale of + item','名词，指把商品或财产卖出的行为。','property changes hands.','商业'),C('sale.s2','零售','Winter coats are on sale this week at a lower price.','本周冬季外套正在降价出售。','on sale; a summer/end-of-season sale','指商品打折出售的一段时间。','prices reduced.','零售'),C('sale.s3','商业','Online sale of the new book doubled after the review appeared.','书评刊出后，这本新书的销量翻了一倍。','sales/sale of + product; boost sales','也可指售出商品的数量或金额。','units sold increase.','商业')],M('The house was for sale, but its owner had refused every offer and no sale took place.','The house was for sale and changed hands after the buyer’s offer was accepted.','for sale只是待售；sale作为成交不能说在无人接受报价时已经发生。','distinction'),[Q(1,'The sale of a house is…','the act of transferring it to a buyer for payment','the period when the house is painted','a ladder used to climb its roof','Sale sense 1 is the act of selling.','meaning'),Q(2,'A store’s winter sale means…','goods are temporarily offered at lower prices','the store has stopped selling forever','the store’s salary bill','A sale can be a discount period.','context'),Q(3,'If a book’s sale doubled, its…','number or value sold increased twofold','cover became twice as large','price was necessarily cut in half','Sale can mean quantity or value sold.','meaning'),Q(2,'Which phrase is standard?','on sale this week','in sale of this week','at the saleing week','On sale means available at a reduced price.','grammar')]);
P('sales','Sales is the plural of sale; it means the amount of goods sold in a period or the work/department responsible for selling them.',[C('sales.s1','商业','Online sales rose sharply after the company offered free delivery.','公司提供免费配送后，线上销售额大幅增长。','sales rose/fell; sales of + product','名词，指某时期售出的商品总量或金额。','more products sold.','商业'),C('sales.s2','工作','She moved from customer support to sales and now visits retailers.','她从客户支持部门转到销售部，现在会拜访零售商。','work in sales; sales department/team','也指销售工作或从事销售的部门。','role focuses on selling.','工作')],M('The company said its sales increased, but clarified that it meant fewer goods were sold and less revenue came in.','The company said its sales increased because more goods were sold or revenue rose.','销售额增加与售出量/收入下降含义相反。','meaning'),[Q(1,'A company’s sales rose in May. This most likely means…','it sold more goods or earned more from sales','it paid more to repair its roof','it hired fewer salespeople by definition','Sales sense 1 measures goods sold.','meaning'),Q(2,'Someone who works in sales is involved in…','selling goods to customers','designing only the factory’s roof','calculating rainfall runoff','Sales can name the selling function or department.','context'),Q(1,'Which phrase is natural?','work in sales','work into salesing','work at the salesly','Work in sales describes the occupation.','grammar'),Q(1,'Car sales can refer to…','the number or value of cars sold','only the people who repair cars','the cost of a car’s salary bill','Sales sense 1 is a measure of units or revenue sold.','meaning')]);
P('salesman','Salesman combines sale and man; it traditionally names a man who sells goods or, figuratively, someone persuasive at promoting an idea.',[C('salesman.s1','工作','The salesman demonstrated the vacuum cleaner and explained its warranty.','男销售员演示了吸尘器，并说明其保修条款。','a traveling/door-to-door salesman','名词，指受雇售货的男性。','employee presents product.','工作'),C('salesman.s2','口语','He is a natural salesman who can make even a complicated proposal sound appealing.','他天生擅长推销，能把复杂提案也讲得很有吸引力。','a born/good salesman','也可泛指擅长说服别人购买或接受想法的人。','persuasive presentation.','口语')],M('The salesman refused to show, explain, or sell any goods to customers.','The salesman demonstrated the goods and helped customers choose what to buy.','拒绝售货不能说明其职业是销售员。','meaning'),[Q(1,'A salesman in a shop is…','a man employed to sell goods','a customer buying a product','a repair tool for a sale','Sense 1 names a male sales worker.','meaning'),Q(2,'Calling a politician a born salesman suggests the politician…','is persuasive at promoting ideas','works as a ship’s sailor','is unable to speak to voters','The figurative sense means skilled at persuading others.','context'),Q(1,'Which phrase is natural?','a car salesman','a salesman of carly at','a salesmanship car','Salesman commonly combines with the product sold.','collocation'),Q(1,'Which form is gender-neutral?','salesperson','salesman','saleswoman','Salesperson avoids specifying a person’s gender.','usage')]);
P('salesmanship','Salesmanship combines salesman/sales with -ship, a suffix naming a skill or quality; it is the ability to sell or present an idea persuasively.',C('salesmanship.s1','商业','Her salesmanship turned hesitant visitors into customers without making exaggerated claims.','她没有夸大其词，却凭借销售技巧把犹豫的访客变成了顾客。','good/effective salesmanship; show salesmanship','名词，指销售能力或有说服力地介绍想法的技巧。','clear pitch persuades buyers.','商业'),M('The proposal lacked salesmanship because its presenter explained no benefits and gave customers no reason to consider it.','The proposal showed salesmanship by clearly explaining its benefits and answering concerns.','salesmanship需要有说服力地呈现价值。','meaning'),[Q(1,'Salesmanship is…','the skill of selling or presenting an idea persuasively','the total wages paid by a company','the act of climbing a ladder','Salesmanship names persuasive selling ability.','meaning'),Q(1,'A presentation with good salesmanship will…','make the value clear to its audience','hide all benefits from potential buyers','focus only on the presenter’s salary','The skill involves persuasive presentation.','context'),Q(1,'Which phrase is natural?','show good salesmanship','show salesmanshiply good','salesmanship of to showing','Show salesmanship is a natural phrase.','collocation'),Q(1,'The suffix -ship in salesmanship helps name…','a skill or quality','a place where ships are stored','a past-tense action','Here -ship forms an abstract noun for an ability.','word-formation')]);
P('salespeople','Salespeople is the gender-neutral plural of salesperson, naming men and women employed to sell goods in shops or directly to customers.',C('salespeople.s1','工作','The salespeople answered questions about the equipment and showed customers the controls.','销售人员回答了有关设备的问题，并向顾客展示操作装置。','salespeople in a shop/on the road','复数名词，指从事售货工作的男女员工。','staff assist buyers.','工作'),M('The store’s salespeople were all customers who had no job or responsibility for selling anything.','The store’s salespeople were employees who helped customers choose and buy products.','无售货职责的顾客不是salespeople。','meaning'),[Q(1,'Salespeople are…','men and women employed to sell goods','the goods being sold','people who only repair a runway','Salespeople is the plural for people in sales jobs.','meaning'),Q(1,'Salespeople in a shop may…','answer product questions and help customers buy','write the store’s etymology entries only','set election runoff rules','Their work involves selling products to customers.','context'),Q(1,'Which form is plural?','salespeople','salesperson','saleswoman','Salespeople is the plural of salesperson.','grammar'),Q(1,'Salespeople is the plural of…','salesperson','salesmanship','sale price','It names multiple people employed to sell goods.','word-formation')]);
P('salesperson','Salesperson combines sales and person; it is a gender-neutral noun for someone employed to sell goods in a shop or directly to customers.',C('salesperson.s1','工作','A salesperson helped us compare the two cameras before we chose one.','一位销售人员帮助我们比较两款相机，然后我们才作出选择。','a salesperson in/at a store; salespeople','名词，指受雇售货的人，不限定性别。','employee helps customer choose.','工作'),M('The salesperson was the shopper buying a camera, not the employee who presented the products.','The salesperson was the employee who explained the cameras to the shopper.','salesperson指售货员，不是来购物的顾客。','distinction'),[Q(1,'A salesperson is…','a person employed to sell goods','a person buying an item for private use','a document listing salary payments','Salesperson names a sales worker.','meaning'),Q(1,'The salesperson compared two cameras for a shopper. The salesperson…','helped the shopper choose a product','was necessarily the shopper’s child','repaired a sailfish fin','Explaining and comparing products is sales work.','context'),Q(1,'Which sentence uses salesperson correctly?','A salesperson showed us the new model.','A salesperson were the products on the shelf.','A salespeople showed us one model.','The singular noun takes a singular verb.','grammar'),Q(1,'Which is the plural of salesperson?','salespeople','salesmans','saleswomans','Salespeople is the standard plural.','word-formation')]);
P('saleswoman','Saleswoman combines sale and woman; it names a woman employed to sell goods, while salesperson is the gender-neutral alternative.',C('saleswoman.s1','工作','The saleswoman demonstrated the camera’s low-light setting twice.','女销售员两次演示了相机的弱光设置。','a saleswoman in a shop; saleswomen','名词，指向顾客售货的女性。','employee demonstrates camera.','工作'),M('The saleswoman demonstrated the camera, although the word means a woman who buys products rather than sells them.','The saleswoman demonstrated the camera as an employee who sells products.','saleswoman指女性售货员，不是女性顾客。','meaning'),[Q(1,'A saleswoman is…','a woman employed to sell goods','a woman who only buys goods','a device used to safeguard a shop','Saleswoman names a female sales worker.','meaning'),Q(1,'Which sentence uses saleswoman naturally?','The saleswoman explained the warranty to us.','The saleswoman were explaining the warranty.','The saleswoman is a plural of salesperson.','The singular noun takes a singular verb.','grammar'),Q(1,'What is a gender-neutral alternative to saleswoman?','salesperson','salesman only','salary bill','Salesperson does not specify gender.','usage'),Q(1,'Which plural form is correct?','saleswomen','saleswomans','saleswomanes','The plural of woman is women, giving saleswomen.','word-formation')]);
P('salient','From Latin salient-, the stem of salire “leap”; salient first described projecting features and now means conspicuous or especially important.',[C('salient.s1','通用','The bright red warning label was the most salient feature of the package.','鲜红的警示标签是包装上最醒目的特征。','a salient feature/detail','形容词，表示突出、容易被注意到。','bright label stands out.','通用'),C('salient.s2','讨论','Before deciding, the committee returned to the salient point about long-term costs.','作决定前，委员会回到了有关长期成本的关键要点。','the salient point/fact/issue','也表示讨论中最重要、最值得关注的。','key issue guides decision.','讨论')],M('The salient detail was impossible to notice and had no importance to the committee’s decision.','The salient detail stood out and mattered to the committee’s decision.','显眼或关键的细节不应同时不可察觉且毫不重要。','meaning'),[Q(1,'A salient feature is one that…','stands out and is easy to notice','is hidden and irrelevant','belongs to a sailing boat','Salient sense 1 means conspicuous.','meaning'),Q(2,'The salient point in a discussion is…','the most important point','the last word alphabetically','a minor detail no one considered','Sense 2 is the central or most relevant issue.','context'),Q(1,'Which phrase is natural?','a salient fact','a salience factly','a saliently fact','Salient is an adjective modifying fact.','grammar'),Q(1,'The Latin verb behind salient meant…','leap','sell','salt','Salient derives from a form of salire, “to leap.”','word-formation')]);
P('saliferous','Saliferous combines Latin sal “salt” with -ferous from ferre “to bear”; it describes rocks or strata that contain or yield salt.',C('saliferous.s1','地质','The survey located a saliferous layer beneath the dry basin.','勘测在干涸盆地下面发现了一层含盐地层。','saliferous rock/stratum/deposit','形容词，指含盐或产盐的地质材料。','salt-bearing layer identified.','地质'),M('The geologist called the saliferous layer salt-bearing even though laboratory tests found no salt in it.','The geologist called the layer saliferous after tests confirmed its salt content.','不含盐的地层不符合saliferous“含盐”的意思。','meaning'),[Q(1,'A saliferous stratum is…','a geological layer that bears or contains salt','a layer made only of fresh water','a plant used in salad','Saliferous means salt-bearing.','meaning'),Q(1,'Where might a geologist find saliferous rock?','in a deposit containing salt','in a cloud above a runway','inside a salary statement','The word describes rocks or strata with salt.','context'),Q(1,'Which noun can saliferous naturally modify?','stratum','salesperson','sailing','Saliferous stratum is a natural technical phrase.','collocation'),Q(1,'The element -ferous is related to a Latin verb meaning…','bear or carry','speak softly','be safe','Ferous formations mean bearing or containing something.','word-formation')]);
P('saline','From Latin salinus, from sal “salt”; saline means containing or tasting of salt, a medically prepared salt solution, or sterile salt water used in care.',[C('saline.s1','环境','Only salt-tolerant grasses survived around the saline lake.','只有耐盐草种在这片咸水湖周边存活下来。','saline water/soil; saline taste','形容词，指含盐或有咸味的。','salty water supports certain plants.','环境'),C('saline.s2','医学','The nurse prepared a saline solution to rinse the patient’s wound.','护士配制了生理盐水来冲洗病人的伤口。','a saline solution','形容词，指盐浓度与体液相当的溶液。','solution prepared for rinsing.','医学'),C('saline.s3','医学','The clinic keeps sterile saline in small bottles for cleaning minor cuts.','诊所把无菌盐水装在小瓶里，用于清洁轻微割伤。','sterile saline; rinse with saline','名词，指用于冲洗伤口或补液的无菌盐水。','sterile liquid cleans cut.','医学')],M('The nurse rinsed the wound with saline, a sterile liquid containing no salt at all.','The nurse rinsed the wound with saline, a sterile salt-water solution.','saline含盐，不是完全无盐液体。','meaning'),[Q(1,'Saline lake water is…','water containing salt','water with no dissolved substances','a bag of flour','Saline means salty or containing salt.','meaning'),Q(2,'A saline solution used in a clinic is…','salt water prepared at a suitable concentration','sugar syrup for baking','a sack used in a farm','Medical saline is a prepared salt solution.','context'),Q(3,'The clinic cleaned a cut with saline. Here saline is…','sterile salt water','a salty adjective before lake','a spicy herb','Saline as a noun names sterile salt water.','meaning'),Q(1,'Which phrase is standard?','saline solution','saline of solutioning','solution saline to a','Saline solution is the standard collocation.','collocation')]);
P('salinity','Salinity is formed from saline + -ity and names the concentration or level of salt in seawater or soil.',[C('salinity.s1','海洋','Scientists measured the sea’s salinity at several depths near the estuary.','科学家测量了河口附近不同深度海水的盐度。','salinity of seawater; high/low salinity','名词，指海水中盐分的含量。','water samples tested for salt.','海洋'),C('salinity.s2','农业','High soil salinity prevented the young wheat from absorbing enough water.','土壤盐度过高，妨碍了幼麦吸收足够的水分。','soil salinity; salinity level','也指土壤中的含盐水平。','salty soil harms plants.','农业')],M('The soil had high salinity, meaning it contained almost no salt and allowed crops to absorb water easily.','The soil had high salinity, meaning excess salt made it harder for crops to grow.','high salinity表示含盐量高，不是几乎无盐。','meaning'),[Q(1,'Seawater salinity measures…','how much salt the water contains','how deep the ocean is','how quickly a ship sails','Salinity is the quantity of salt in water.','meaning'),Q(2,'High soil salinity can…','make crop growth difficult','turn soil into a safe deposit box','remove all minerals from soil','Too much salt in soil harms plant growth.','context'),Q(1,'Which phrase is natural?','measure the salinity of seawater','measure salinityly of sea','measure the saline of seawaterity','Salinity is the noun for a salt level.','grammar'),Q(1,'The suffix -ity in salinity forms…','a noun naming a state or quality','a person who sells salt','a verb meaning add salt','Salinity names the state or level of being saline.','word-formation')]);
P('salinization','Salinization is formed from salinize + -ation, based on saline from Latin sal “salt”; it names an increase of salt in soil or water, often damaging land.',C('salinization.s1','农业','Poor drainage caused salinization of the irrigated fields and reduced the harvest.','排水不良导致灌溉田盐渍化，收成随之下降。','soil salinization; prevent salinization','名词，指土壤或水体盐分增加的过程。','salts accumulate in fields.','农业'),M('Salinization restored the fields by removing accumulated salts and making the soil less saline.','Salinization damaged the fields as salts accumulated in the soil.','盐渍化是含盐量增加，不是脱盐修复。','meaning'),[Q(1,'Salinization is…','an increase of salt in soil or water','a reduction in every soil mineral','the process of removing rust from iron','Salinization means increasing salinity.','meaning'),Q(1,'Why can salinization harm a farm?','Accumulated salts can damage crops and reduce yields.','It always turns soil into fresh water.','It gives crops more rainfall.','Excess salt can make soil unsuitable for crops.','context'),Q(1,'Which phrase is natural?','soil salinization','salinize soiling ation','salinization of no salt','The process is commonly described as soil salinization.','collocation'),Q(1,'Salinization is related to the word…','saline','sailfish','saintly','The term derives from saline and names increasing salt content.','word-formation')]);
P('saliva','From Latin saliva “spittle”; saliva is the thin fluid made in the mouth that moistens food and helps digestion.',C('saliva.s1','生理','Saliva began to soften the cracker before he swallowed it.','他吞下饼干前，唾液已开始把它润软。','produce/swallow saliva; saliva in the mouth','不可数名词，指口腔中帮助润湿和消化食物的液体。','mouth fluid softens food.','生理'),M('Saliva is the solid bone that moves food through the stomach after it is swallowed.','Saliva is the thin mouth fluid that moistens food before swallowing.','唾液是口腔液体，不是骨头。','meaning'),[Q(1,'Saliva is…','a thin fluid produced in the mouth','a solid part of the skeleton','a salt-bearing rock','Saliva is the mouth liquid that helps soften food.','meaning'),Q(1,'Saliva helps with food by…','moistening it and aiding digestion','making it impossible to swallow','turning it into rust','The fluid helps prepare food for swallowing and digestion.','context'),Q(1,'Which phrase is natural?','produce saliva','saliva a production','produce salivated saliva','The body produces saliva.','collocation'),Q(1,'The Latin source saliva meant…','spittle','a story','a sword','Saliva comes directly from Latin saliva.','word-formation')]);
P('salivate','Salivate is formed from saliva + -ate; it means produce saliva in response to food or, figuratively, show intense desire for something.',[C('salivate.s1','生理','The dog began to salivate when it smelled the roast chicken.','狗闻到烤鸡的香味后开始流口水。','salivate at the smell/sight of food','动词，指口腔分泌唾液，常由食物刺激。','food odor triggers response.','生理'),C('salivate.s2','口语','Investors salivated over the prospect of a contract that could double their revenue.','投资者对一份可能让收入翻倍的合同垂涎不已。','salivate over + desired thing','比喻表示对某物非常渴望，旁人也看得出来。','strong eagerness for contract.','口语')],M('The dog salivated at the smell of dinner, yet its mouth remained completely dry and produced no saliva.','The dog salivated at the smell of dinner, with saliva forming in its mouth.','salivate本义就是分泌唾液，不能说口腔完全干燥且无唾液。','meaning'),[Q(1,'A dog may salivate when it…','smells food','hears a ladder rung creak','runs out of water only','Food or its smell can trigger saliva production.','meaning'),Q(2,'Investors salivated over a contract means they…','strongly desired the contract','had already rejected every offer','were physically standing in salt water','The figurative sense means show eager desire.','context'),Q(1,'Which phrase is natural?','salivate over the opportunity','salivate at opportunitying over','salivation the opportunity with','Salivate over is a common figurative construction.','grammar'),Q(1,'Salivate is formed from saliva plus…','-ate','-ness','-ship','The suffix -ate helps form the verb salivate.','word-formation')]);
P('sallow','The sickly-yellow skin sense is recorded in Old English salo; the separate willow-tree name has a different, uncertain history. Sallow can name either.',[C('sallow.s1','外貌','After weeks indoors, his skin looked sallow and tired.','在室内待了数周后，他的皮肤显得蜡黄而疲惫。','sallow skin/complexion','形容词，指皮肤呈不健康的黄或浅褐色。','complexion appears unhealthy.','外貌'),C('sallow.s2','植物','A sallow grew beside the damp ditch where the ground stayed wet all year.','一株黄花柳长在潮湿的沟渠旁，那里的地面常年湿润。','a sallow tree/shrub','名词，指生长于湿地的一种柳属灌木或树。','willow grows in wet place.','植物')],M('The doctor described his complexion as sallow because it was bright pink, healthy, and full of colour.','The doctor described his complexion as sallow because it looked unhealthy and yellowish.','健康红润的肤色与病态蜡黄的sallow相反。','meaning'),[Q(1,'Sallow skin looks…','unhealthily yellow or pale brown','bright green and metallic','covered in dark blue scales','Sallow sense 1 describes an unhealthy yellowish complexion.','meaning'),Q(2,'A sallow beside a wet ditch is…','a willow of damp ground','a salty solution','a type of salesperson','The noun sense names a willow shrub or tree.','context'),Q(1,'Which phrase is natural?','a sallow complexion','a sallowly complexionness','a complexion of sallowing at','Sallow complexion is a common pairing.','collocation'),Q(1,'The plant and skin senses of sallow…','have distinct histories, with the tree-name origin uncertain','both definitely come from Latin for salt','are two spellings of saliva','The dictionary distinguishes the willow name from the adjective’s history.','word-formation')]);
P('salmon','From Old French saumon and Latin salmonem; salmon names a migratory fish with pink flesh or a color resembling that flesh.',[C('salmon.s1','动物','The salmon returned from the ocean and swam upstream to spawn.','鲑鱼从海洋洄游回来，逆流而上产卵。','wild/farmed salmon; salmon migrate upstream','名词，指洄游产卵、肉色粉红的大型鱼类。','fish migrates to river.','动物'),C('salmon.s2','颜色','The living room walls were painted a soft salmon pink.','客厅墙壁刷成了柔和的鲑鱼粉。','salmon pink; salmon-coloured','名词作颜色名，指橙粉色。','paint has pink-orange tone.','颜色')],M('The salmon swam downstream away from its spawning grounds and was described as a land-dwelling bird.','The salmon swam upstream to its spawning grounds as a migratory fish.','salmon是鱼类，常洄游逆流产卵。','meaning'),[Q(1,'A salmon is known as a fish that…','swims upstream to lay eggs','lives only in dry desert soil','has a sail-shaped dorsal fin','Salmon migrate up rivers to spawn.','meaning'),Q(2,'Salmon pink is…','a pink-orange colour like the fish’s flesh','a deep green leaf colour','a shade of rustproof steel','The color sense resembles salmon flesh.','context'),Q(1,'Which phrase is natural?','smoked salmon','smoked salmons pinkly','a salmon of color to','Smoked salmon is a common food phrase.','collocation'),Q(1,'Which sentence uses salmon as a color?','The designer chose a salmon sofa.','A salmon fought its way upstream.','We grilled a salmon for dinner.','Here salmon modifies sofa as a color name.','meaning')]);
P('salmonberry','Salmonberry combines salmon and berry; it names Rubus spectabilis, a northwestern North American shrub with raspberry-like edible fruit.',C('salmonberry.s1','植物','The salmonberry bushes along the trail produced orange-pink fruit in early summer.','步道旁的悬钩子灌木在初夏结出橙粉色果实。','salmonberry bush/fruit; pick salmonberries','名词，指北美西北部的一种悬钩子属灌木及其可食果实。','fruit ripens on shrub.','植物'),M('The botanist called an apple tree salmonberry even though salmonberry is a northwestern shrub with raspberry-like fruit.','The botanist identified the northwestern shrub with raspberry-like fruit as salmonberry.','salmonberry不是苹果树，而是悬钩子属灌木。','distinction'),[Q(1,'Salmonberry is…','a shrub of northwestern North America with raspberry-like fruit','a kind of salmon fish','a salt-bearing rock','It names Rubus spectabilis and its fruit.','meaning'),Q(1,'What fruit might grow on a salmonberry bush?','orange-pink raspberry-like berries','large fish with pink flesh','dry grains for bread','The plant bears edible raspberry-like fruit.','context'),Q(1,'Which phrase is natural?','salmonberry fruit','salmonberry fishery of','a salmon berrying pink','Salmonberry names the shrub and its berry-like fruit.','collocation'),Q(1,'Salmonberry is a compound containing…','salmon + berry','sail + berry','salary + berry','The word is built from salmon and berry.','word-formation')]);
P('salon','From French salon, via Italian salone “large room,” from sala “hall”; salon is a beauty-treatment shop or a gathering of writers and artists.',[C('salon.s1','服务','She booked a salon appointment for a haircut and manicure.','她预约了美容店，准备剪发和做美甲。','hair/beauty/nail salon; visit a salon','名词，指提供美发、美甲或美容服务的店。','appointment for treatments.','服务'),C('salon.s2','文化','The poet hosted a weekly salon where writers read new work and debated ideas.','诗人每周举办一次沙龙，作家们在会上朗读新作并讨论观点。','host/attend a salon; a literary salon','名词，也指作家艺术家在私人场所举行的聚会。','writers meet and discuss.','文化')],M('She booked a salon appointment for a haircut, then arrived at a meeting of writers rather than a beauty shop.','She booked a beauty-salon appointment and went to the shop for a haircut.','剪发预约语境中的salon是美发美容店，不是文学聚会。','context'),[Q(1,'A hair salon is…','a shop where hair is cut or styled','a meeting of sailors on a ship','a storehouse for salt','Salon sense 1 is a beauty-treatment business.','meaning'),Q(2,'A literary salon is…','a gathering where writers and artists exchange ideas','a salon that sells shampoo only','a type of election runoff','Sense 2 refers to a cultural meeting.','context'),Q(1,'Which phrase is natural?','book a salon appointment','book salon to appointmenting','salon appointment at to book of','One books an appointment at a salon.','collocation'),Q(1,'Salon entered English from French, ultimately related to an Italian word for…','a large room or hall','a small bag','a grain plant','The word traces through Italian salone to sala, “hall.”','word-formation')]);
P('salt','From Old English sealt, a Germanic word; salt is a seasoning mineral, to add or preserve with it, or figuratively something that gives life or writing character.',[C('salt.s1','烹饪','Add a pinch of salt after tasting the soup so it does not become too salty.','先尝尝汤，再加一撮盐，免得太咸。','a pinch of salt; salt and pepper','名词，指用于调味的白色矿物质。','seasoning added to soup.','烹饪'),C('salt.s2','烹饪','They salted the fish before drying it for the journey.','他们把鱼腌了盐，再晒干带上旅途。','salt food/fish; salted meat','动词，指加盐调味或用盐保存食物。','salt preserves fish.','烹饪'),C('salt.s3','比喻','A little humour is the salt of the story, keeping its serious message lively.','一点幽默是这个故事的调味料，让严肃主题也生动起来。','the salt of + story/life/earth','比喻名词，指使生活或叙述更有滋味的元素。','humor adds liveliness.','比喻')],M('The cook salted the soup by removing every grain of salt and adding only plain water.','The cook salted the soup by adding a measured amount of salt.','加盐调味与去掉所有盐相反。','meaning'),[Q(1,'Salt in soup is used to…','season the food','make the soup a ladder rung','turn it into a salon','Salt sense 1 is a seasoning.','meaning'),Q(2,'To salt fish before drying it is to…','add salt to help preserve it','rinse every trace of salt away','serve it as a salad without preparation','Salt as a verb includes preserving food.','context'),Q(3,'“Humour is the salt of the story” means humour…','makes the story more lively or interesting','is literally sprinkled into the pages','makes the story impossible to read','The figurative sense is something that adds character.','meaning'),Q(1,'Which phrase is natural?','a pinch of salt','a pinch salty of','salt a pinch to the of','Pinch of salt names a small amount.','collocation')]);
})();
